// CPC (Lei 13.105/2015) — escopo do edital: arts. 144–155, 188–275, 294–311, 318–538 e 994–1026.
// Cartões em molde Vunesp; 'caiu' = questão de prova anterior.
window.CARDS = (window.CARDS || []).concat([
  { id: "cpc-1", lei: "CPC", ref: "CPC art. 144",
    frente: "Impedimento do juiz no processo civil (art. 144): hipóteses.",
    verso: "O juiz é IMPEDIDO quando: I interveio como mandatário da parte, oficiou como perito, funcionou como membro do MP ou prestou depoimento como testemunha; II conheceu do processo em outro grau de jurisdição, tendo proferido decisão; III nele postula, como defensor público, advogado ou membro do MP, seu cônjuge, companheiro ou parente até o 3º grau; IV é parte ele próprio, seu cônjuge, companheiro ou parente até o 3º grau; V é sócio ou membro de direção ou administração de pessoa jurídica parte; VI é herdeiro presuntivo, donatário ou empregador de qualquer das partes; VII figura como parte instituição de ensino com a qual tenha relação de emprego ou contrato de serviços; VIII figura como parte cliente do escritório de advocacia de seu cônjuge, companheiro ou parente até o 3º grau; IX promove ação contra a parte ou seu advogado." },
  { id: "cpc-2", lei: "CPC", ref: "CPC art. 144, §§1º a 3º",
    frente: "Impedimento por inciso III (art. 144, §§1º a 3º): condições.",
    verso: "§1º: só se verifica quando o defensor público, advogado ou membro do MP JÁ INTEGRAVA o processo antes do início da atividade judicante do juiz. §2º: é VEDADA a criação de fato superveniente para caracterizar impedimento. §3º: também se verifica no mandato conferido a membro de escritório de advocacia que tenha em seus quadros advogado que ostente a condição do inciso III, mesmo que não intervenha diretamente." },
  { id: "cpc-3", lei: "CPC", ref: "CPC art. 145 · já caiu: 2014, 2017, 2021",
    frente: "Suspeição do juiz no processo civil (art. 145): hipóteses.",
    verso: "O juiz é SUSPEITO quando: I amigo ÍNTIMO ou INIMIGO de qualquer das partes ou de seus advogados; II receber PRESENTES de pessoas com interesse na causa, ACONSELHAR alguma das partes acerca do objeto da causa ou subministrar meios para atender às despesas do litígio; III qualquer das partes for sua CREDORA ou DEVEDORA, de seu cônjuge ou companheiro ou de parentes destes em linha reta até o 3º grau; IV for INTERESSADO no julgamento em favor de qualquer das partes." },
  { id: "cpc-4", lei: "CPC", ref: "CPC art. 145, §§1º e 2º",
    frente: "Suspeição por foro íntimo e alegação ilegítima (art. 145, §§1º e 2º).",
    verso: "§1º: o juiz pode declarar-se suspeito por motivo de FORO ÍNTIMO, sem necessidade de declarar as razões. §2º: é ILEGÍTIMA a alegação de suspeição quando: I houver sido PROVOCADA por quem a alega; II a parte que a alega houver praticado ato que signifique manifesta ACEITAÇÃO do arguido." },
  { id: "cpc-5", lei: "CPC", ref: "CPC art. 146 · já caiu: 2023",
    frente: "Como se alega impedimento ou suspeição do juiz (art. 146): prazo e forma.",
    verso: "No prazo de 15 DIAS, a contar do conhecimento do fato, a parte alegará o impedimento ou a suspeição, em PETIÇÃO ESPECÍFICA dirigida ao juiz do processo, indicando o fundamento da recusa, podendo instruí-la com documentos e rol de testemunhas. Se o juiz reconhecer, ordena imediatamente a remessa dos autos ao SUBSTITUTO LEGAL; se não, autua em apartado a petição e, em 15 DIAS, apresenta suas razões e remete o incidente ao TRIBUNAL (§1º)." },
  { id: "cpc-6", lei: "CPC", ref: "CPC art. 146, §§2º a 7º · já caiu: 2017, 2023",
    frente: "Incidente de impedimento ou suspeição no tribunal (art. 146, §§2º a 7º).",
    verso: "§2º: distribuído o incidente, o relator declara os EFEITOS: sem efeito suspensivo, o processo volta a correr; com efeito suspensivo, permanece suspenso. §3º: enquanto não declarado o efeito ou se suspensivo, a TUTELA DE URGÊNCIA é requerida ao SUBSTITUTO LEGAL. §4º: improcedente, o tribunal rejeita. §5º: acolhida a alegação (impedimento ou manifesta suspeição), o tribunal CONDENA O JUIZ NAS CUSTAS e remete os autos ao substituto legal, podendo o juiz recorrer. §6º: o tribunal fixa o MOMENTO a partir do qual o juiz não poderia ter atuado. §7º: decreta a NULIDADE dos atos praticados já presente o motivo." },
  { id: "cpc-7", lei: "CPC", ref: "CPC art. 147",
    frente: "Juízes parentes (art. 147).",
    verso: "Quando 2 ou mais juízes forem parentes, consanguíneos ou afins, em linha reta ou colateral, até o 3º GRAU, inclusive, o PRIMEIRO que conhecer do processo impede que o outro nele atue; o segundo se escusa, remetendo os autos ao substituto legal." },
  { id: "cpc-8", lei: "CPC", ref: "CPC art. 148 · já caiu: 2021, 2023",
    frente: "A quem se aplicam os motivos de impedimento e suspeição, além do juiz (art. 148)?",
    verso: "I ao membro do MINISTÉRIO PÚBLICO; II aos AUXILIARES DA JUSTIÇA; III aos demais sujeitos imparciais do processo. A parte arguirá, em petição fundamentada, na PRIMEIRA OPORTUNIDADE em que lhe couber falar nos autos (§1º). O juiz processa o incidente EM SEPARADO e SEM suspensão do processo, ouvindo o arguido em 15 DIAS (§2º). Não se aplica à arguição contra TESTEMUNHA (§4º)." },
  { id: "cpc-9", lei: "CPC", ref: "CPC art. 149",
    frente: "Quem são os auxiliares da Justiça (art. 149)?",
    verso: "Além de outros previstos na organização judiciária: o ESCRIVÃO, o CHEFE DE SECRETARIA, o OFICIAL DE JUSTIÇA, o PERITO, o DEPOSITÁRIO, o ADMINISTRADOR, o INTÉRPRETE, o TRADUTOR, o MEDIADOR, o CONCILIADOR judicial, o PARTIDOR, o DISTRIBUIDOR, o CONTABILISTA e o REGULADOR DE AVARIAS." },
  { id: "cpc-10", lei: "CPC", ref: "CPC arts. 150 e 151",
    frente: "Ofícios de justiça e número de oficiais (arts. 150 e 151).",
    verso: "Art. 150: em cada juízo haverá um ou mais OFÍCIOS DE JUSTIÇA, cujas atribuições são determinadas pelas normas de organização judiciária. Art. 151: em cada comarca, seção ou subseção judiciária haverá, no mínimo, TANTOS OFICIAIS DE JUSTIÇA quantos sejam os juízos." },
  { id: "cpc-11", lei: "CPC", ref: "CPC art. 152, I a VI · já caiu: 2013, 2015, 2018",
    frente: "O que incumbe ao escrivão ou chefe de secretaria (art. 152)?",
    verso: "I redigir, na forma legal, ofícios, mandados, cartas precatórias e demais atos do seu ofício; II efetivar as ordens judiciais, realizar CITAÇÕES e INTIMAÇÕES e praticar os demais atos que lhe forem atribuídos; III comparecer às AUDIÊNCIAS ou, não podendo, designar servidor para substituí-lo; IV manter sob sua GUARDA e responsabilidade os autos, que não saem do cartório, EXCETO: a) conclusão ao juiz; b) vista a procurador, Defensoria, MP ou Fazenda Pública; c) remessa ao contabilista ou partidor; d) remessa a outro juízo por modificação de competência; V fornecer CERTIDÃO de qualquer ato ou termo do processo, INDEPENDENTEMENTE DE DESPACHO, observado o segredo de justiça; VI praticar, de ofício, os atos meramente ORDINATÓRIOS." },
  { id: "cpc-12", lei: "CPC", ref: "CPC art. 152, §§1º e 2º",
    frente: "Regulamentação dos atos ordinatórios e impedimento do escrivão (art. 152, §§1º e 2º).",
    verso: "§1º: o JUIZ TITULAR edita ato para regulamentar a atribuição dos atos meramente ordinatórios (inciso VI). §2º: no impedimento do escrivão ou chefe de secretaria, o juiz convoca SUBSTITUTO e, não o havendo, nomeia PESSOA IDÔNEA para o ato." },
  { id: "cpc-13", lei: "CPC", ref: "CPC art. 153 · caiu 2024 Q38",
    frente: "Ordem cronológica de publicação e efetivação dos pronunciamentos (art. 153): regra, exceções e preterição.",
    verso: "O escrivão ou chefe de secretaria atenderá, PREFERENCIALMENTE, à ORDEM CRONOLÓGICA de recebimento para publicação e efetivação dos pronunciamentos judiciais. A lista de processos recebidos é disponibilizada de forma PERMANENTE para consulta pública (§1º). Excluídos da regra: I os atos URGENTES, reconhecidos pelo juiz; II as PREFERÊNCIAS LEGAIS (§2º). Preterição: a parte reclama NOS PRÓPRIOS AUTOS, ao juiz, que requisita informações ao servidor, a serem prestadas em 2 DIAS (§4º). Constatada, o juiz determina o IMEDIATO CUMPRIMENTO do ato e a instauração de PROCESSO ADMINISTRATIVO DISCIPLINAR contra o servidor (§5º)." },
  { id: "cpc-14", lei: "CPC", ref: "CPC art. 154 · já caiu: 2013, 2018",
    frente: "O que incumbe ao oficial de justiça (art. 154)?",
    verso: "I fazer PESSOALMENTE citações, prisões, penhoras, arrestos e demais diligências, sempre que possível na presença de 2 TESTEMUNHAS, certificando no mandado o ocorrido, com lugar, dia e hora; II executar as ordens do juiz; III entregar o mandado em cartório após o cumprimento; IV auxiliar o juiz na manutenção da ordem; V efetuar avaliações; VI certificar em mandado a PROPOSTA DE AUTOCOMPOSIÇÃO apresentada por qualquer das partes na ocasião do ato de comunicação. Certificada, o juiz ordena a intimação da parte contrária para manifestar-se em 5 DIAS; o SILÊNCIO é recusa (parágrafo único)." },
  { id: "cpc-15", lei: "CPC", ref: "CPC art. 155",
    frente: "Responsabilidade civil do escrivão, chefe de secretaria e oficial de justiça (art. 155).",
    verso: "São responsáveis, CIVIL e REGRESSIVAMENTE, quando: I sem justo motivo, se recusarem a cumprir no prazo os atos impostos pela lei ou pelo juiz a que estão subordinados; II praticarem ato nulo com DOLO ou CULPA." },
  { id: "cpc-16", lei: "CPC", ref: "CPC art. 188",
    frente: "Forma dos atos processuais (art. 188).",
    verso: "Os atos e termos processuais INDEPENDEM de forma determinada, salvo quando a lei expressamente a exigir, considerando-se válidos os que, realizados de outro modo, lhe preencham a FINALIDADE ESSENCIAL." },
  { id: "cpc-17", lei: "CPC", ref: "CPC art. 189 · já caiu: 2006, 2007, 2017, 2018, 2023",
    frente: "Segredo de justiça (art. 189): quais processos tramitam em segredo?",
    verso: "Os atos processuais são públicos, mas tramitam em SEGREDO DE JUSTIÇA os processos: I em que o exija o interesse público ou social; II que versem sobre CASAMENTO, SEPARAÇÃO DE CORPOS, DIVÓRCIO, SEPARAÇÃO, UNIÃO ESTÁVEL, FILIAÇÃO, ALIMENTOS e GUARDA de crianças e adolescentes; III em que constem dados protegidos pelo direito constitucional à INTIMIDADE; IV que versem sobre ARBITRAGEM, inclusive cumprimento de carta arbitral, desde que a confidencialidade seja comprovada perante o juízo." },
  { id: "cpc-18", lei: "CPC", ref: "CPC art. 189, §§1º e 2º · já caiu: 2006, 2007",
    frente: "Quem pode consultar autos em segredo de justiça e pedir certidões (art. 189, §§1º e 2º).",
    verso: "§1º: o direito de consultar os autos e pedir certidões é RESTRITO às PARTES e aos seus PROCURADORES. §2º: o TERCEIRO que demonstrar INTERESSE JURÍDICO pode requerer ao juiz certidão do DISPOSITIVO da sentença, bem como de inventário e de partilha resultantes de divórcio ou separação." },
  { id: "cpc-19", lei: "CPC", ref: "CPC art. 190",
    frente: "Negócio jurídico processual (art. 190).",
    verso: "Versando o processo sobre direitos que admitam AUTOCOMPOSIÇÃO, é lícito às partes PLENAMENTE CAPAZES estipular mudanças no procedimento e convencionar sobre ônus, poderes, faculdades e deveres processuais, ANTES ou DURANTE o processo. O juiz controla a validade, recusando aplicação somente nos casos de NULIDADE ou de inserção ABUSIVA em contrato de adesão ou em que alguma parte esteja em manifesta situação de VULNERABILIDADE." },
  { id: "cpc-20", lei: "CPC", ref: "CPC art. 191 · já caiu: 2010, 2014, 2017",
    frente: "Calendário processual (art. 191).",
    verso: "De COMUM ACORDO, o juiz e as partes podem fixar CALENDÁRIO para a prática dos atos processuais. O calendário VINCULA as partes e o juiz, e os prazos só serão modificados em casos EXCEPCIONAIS, justificados (§1º). DISPENSA-SE a intimação das partes para ato ou audiência cujas datas constem do calendário (§2º)." },
  { id: "cpc-21", lei: "CPC", ref: "CPC art. 192 · já caiu: 2006, 2017",
    frente: "Língua dos atos processuais e documento em língua estrangeira (art. 192).",
    verso: "Em todos os atos e termos do processo é OBRIGATÓRIO o uso da LÍNGUA PORTUGUESA. O documento redigido em língua estrangeira somente pode ser juntado acompanhado de VERSÃO para o português tramitada por via DIPLOMÁTICA ou pela AUTORIDADE CENTRAL, ou firmada por TRADUTOR JURAMENTADO." },
  { id: "cpc-22", lei: "CPC", ref: "CPC arts. 193 a 199 · já caiu: 2007, 2010",
    frente: "Prática eletrônica de atos processuais (arts. 193 a 199).",
    verso: "Art. 193: os atos podem ser total ou parcialmente DIGITAIS. Art. 194: os sistemas respeitarão a PUBLICIDADE, o acesso e a participação das partes e procuradores, com disponibilidade, independência de plataforma, acessibilidade e interoperabilidade. Art. 195: o registro do ato eletrônico em padrões ABERTOS, com autenticidade, integridade, temporalidade, não repúdio, conservação e confidencialidade (segredo de justiça). Art. 196: compete ao CNJ e, supletivamente, aos tribunais regulamentar a prática e a comunicação eletrônica. Art. 197: os tribunais divulgam as informações do sistema em página própria, com PRESUNÇÃO de veracidade e confiabilidade. Art. 198: as unidades do Judiciário mantêm GRATUITAMENTE equipamentos para a prática de atos e consulta; admite-se ato por meio não eletrônico onde não disponíveis. Art. 199: assegura-se ACESSIBILIDADE às pessoas com deficiência." },
  { id: "cpc-23", lei: "CPC", ref: "CPC arts. 200 a 202 · já caiu: 2010, 2017",
    frente: "Atos das partes: desistência, recibo e cotas marginais (arts. 200 a 202).",
    verso: "Art. 200: as declarações de vontade produzem imediatamente a constituição, modificação ou extinção de direitos processuais; a DESISTÊNCIA DA AÇÃO só produz efeitos após HOMOLOGAÇÃO JUDICIAL. Art. 201: as partes podem exigir RECIBO de petições e documentos entregues em cartório. Art. 202: é VEDADO lançar nos autos COTAS MARGINAIS ou INTERLINEARES, que o juiz manda riscar, impondo a quem as escrever MULTA correspondente à METADE do salário mínimo." },
  { id: "cpc-24", lei: "CPC", ref: "CPC art. 203 · já caiu: 2010, 2015, 2017",
    frente: "Pronunciamentos do juiz (art. 203).",
    verso: "Consistem em SENTENÇAS, DECISÕES INTERLOCUTÓRIAS e DESPACHOS. SENTENÇA: pronunciamento com fundamento nos arts. 485 e 487 que põe fim à FASE COGNITIVA do procedimento comum ou extingue a EXECUÇÃO. DECISÃO INTERLOCUTÓRIA: todo pronunciamento de natureza decisória que não seja sentença. DESPACHOS: os demais pronunciamentos, de ofício ou a requerimento. Atos meramente ORDINATÓRIOS (juntada, vista obrigatória) INDEPENDEM de despacho, praticados de ofício pelo servidor e revistos pelo juiz quando necessário (§4º)." },
  { id: "cpc-25", lei: "CPC", ref: "CPC arts. 204 e 205 · já caiu: 2010",
    frente: "Acórdão e redação dos pronunciamentos (arts. 204 e 205).",
    verso: "Art. 204: ACÓRDÃO é o julgamento colegiado proferido pelos tribunais. Art. 205: despachos, decisões, sentenças e acórdãos são redigidos, datados e ASSINADOS pelos juízes; se orais, o servidor os documenta e os submete a revisão e assinatura (§1º). A assinatura pode ser ELETRÔNICA (§2º). Despachos, decisões interlocutórias, o DISPOSITIVO das sentenças e a EMENTA dos acórdãos são publicados no DJe (§3º)." },
  { id: "cpc-26", lei: "CPC", ref: "CPC arts. 206 a 208 · já caiu: 2006",
    frente: "Atos do escrivão: autuação, numeração e termos (arts. 206 a 208).",
    verso: "Art. 206: ao receber a petição inicial, o escrivão a AUTUARÁ, mencionando o juízo, a natureza do processo, o número do registro, os nomes das partes e a data de início, e procede do mesmo modo com os volumes em formação. Art. 207: NUMERA e RUBRICA todas as folhas dos autos; parte, procurador, MP, defensor e auxiliares podem rubricar as folhas dos atos em que intervierem. Art. 208: os termos de juntada, vista, conclusão e semelhantes constarão de NOTAS DATADAS e RUBRICADAS pelo escrivão." },
  { id: "cpc-27", lei: "CPC", ref: "CPC arts. 209 a 211",
    frente: "Assinatura dos atos, taquigrafia e espaços em branco (arts. 209 a 211).",
    verso: "Art. 209: os atos e termos são assinados pelas pessoas que neles intervierem; quando não puderem ou não quiserem, o escrivão CERTIFICA a ocorrência. Nos autos eletrônicos, os atos na presença do juiz podem ser armazenados de modo digital, com termo assinado digitalmente pelo juiz, pelo escrivão e pelos advogados (§1º); contradições na transcrição devem ser suscitadas ORALMENTE no ato, sob pena de PRECLUSÃO (§2º). Art. 210: é lícito o uso de TAQUIGRAFIA, ESTENOTIPIA ou outro método idôneo. Art. 211: não se admitem ESPAÇOS EM BRANCO (salvo os inutilizados), ENTRELINHAS, EMENDAS ou RASURAS, exceto quando ressalvadas." },
  { id: "cpc-28", lei: "CPC", ref: "CPC art. 212 · caiu 2025 Q26 · já caiu: 2006, 2012",
    frente: "Tempo dos atos processuais (art. 212): horário, dias e a exceção das citações, intimações e penhoras.",
    verso: "Atos processuais são realizados em DIAS ÚTEIS, das 6 às 20 HORAS. Serão concluídos após as 20h os atos iniciados antes, quando o adiamento prejudicar a diligência ou causar grave dano (§1º). §2º: INDEPENDENTEMENTE DE AUTORIZAÇÃO JUDICIAL, as citações, intimações e PENHORAS podem realizar-se nas férias forenses, nos feriados e em dias úteis fora do horário, observado o art. 5º, XI da CF. §3º: petição em autos não eletrônicos é protocolada no horário de funcionamento do fórum. (Prova 2025: penhora no sábado às 21h, válida, sem autorização.)" },
  { id: "cpc-29", lei: "CPC", ref: "CPC art. 213",
    frente: "Prática eletrônica de ato processual: até que horas (art. 213)?",
    verso: "Pode ocorrer em qualquer horário até as 24 HORAS do último dia do prazo. Considera-se o horário vigente no JUÍZO perante o qual o ato deve ser praticado." },
  { id: "cpc-30", lei: "CPC", ref: "CPC arts. 214 a 216 · já caiu: 2006, 2012, 2018",
    frente: "Férias forenses, feriados e atos que se processam nesse período (arts. 214 a 216).",
    verso: "Art. 214: durante as férias e feriados NÃO se praticam atos processuais, EXCETO: I os do art. 212, §2º (citações, intimações e penhoras); II a TUTELA DE URGÊNCIA. Art. 215: processam-se nas férias, onde houver, e não se suspendem: I procedimentos de JURISDIÇÃO VOLUNTÁRIA e os necessários à conservação de direitos; II a AÇÃO DE ALIMENTOS e os processos de nomeação ou remoção de TUTOR e CURADOR; III os que a lei determinar. Art. 216: além dos declarados em lei, são feriados forenses os SÁBADOS, os DOMINGOS e os dias sem expediente forense." },
  { id: "cpc-31", lei: "CPC", ref: "CPC art. 217",
    frente: "Lugar dos atos processuais (art. 217).",
    verso: "Realizam-se ordinariamente na SEDE DO JUÍZO ou, excepcionalmente, em outro lugar em razão de DEFERÊNCIA, INTERESSE DA JUSTIÇA, NATUREZA DO ATO ou OBSTÁCULO arguido pelo interessado e acolhido pelo juiz." },
  { id: "cpc-32", lei: "CPC", ref: "CPC art. 218 · já caiu: 2007, 2014, 2015",
    frente: "Prazos quando a lei é omissa (art. 218).",
    verso: "Os atos são realizados nos prazos da lei. Lei omissa: o juiz determina o prazo em consideração à COMPLEXIDADE do ato (§1º). Se nem a lei nem o juiz determinar prazo, as intimações só obrigam ao comparecimento após 48 HORAS (§2º). Inexistindo preceito legal ou prazo do juiz, será de 5 DIAS o prazo para ato a cargo da PARTE (§3º). Será tempestivo o ato praticado ANTES do termo inicial (§4º)." },
  { id: "cpc-33", lei: "CPC", ref: "CPC arts. 219 e 220 · já caiu: 2010, 2013, 2014",
    frente: "Contagem em dias úteis e suspensão dos prazos de 20 de dezembro a 20 de janeiro (arts. 219 e 220).",
    verso: "Art. 219: na contagem de prazo em dias, estabelecido por lei ou pelo juiz, computam-se SOMENTE OS DIAS ÚTEIS; aplica-se só aos prazos PROCESSUAIS. Art. 220: SUSPENDE-SE o curso do prazo processual entre 20 DE DEZEMBRO e 20 DE JANEIRO, inclusive. Nesse período, juízes, MP, Defensoria, Advocacia Pública e auxiliares exercem suas atribuições (ressalvadas férias individuais e feriados) e NÃO se realizam audiências nem sessões de julgamento." },
  { id: "cpc-34", lei: "CPC", ref: "CPC art. 221",
    frente: "Suspensão do prazo por obstáculo e por programa de autocomposição (art. 221).",
    verso: "Suspende-se o curso do prazo por OBSTÁCULO criado em detrimento da parte ou ocorrendo qualquer das hipóteses do art. 313, devendo o prazo ser RESTITUÍDO por tempo igual ao que faltava. Suspendem-se os prazos durante a execução de PROGRAMA instituído pelo Poder Judiciário para promover a AUTOCOMPOSIÇÃO." },
  { id: "cpc-35", lei: "CPC", ref: "CPC art. 222 · já caiu: 2013",
    frente: "Prorrogação de prazos em comarca de difícil transporte (art. 222).",
    verso: "O juiz poderá prorrogar os prazos por até 2 (DOIS) MESES. Ao juiz é VEDADO REDUZIR prazos PEREMPTÓRIOS sem anuência das partes (§1º). Havendo CALAMIDADE PÚBLICA, o limite pode ser excedido (§2º)." },
  { id: "cpc-36", lei: "CPC", ref: "CPC art. 223 · já caiu: 2010, 2015",
    frente: "Decurso do prazo e justa causa (art. 223).",
    verso: "Decorrido o prazo, EXTINGUE-SE o direito de praticar ou emendar o ato, INDEPENDENTEMENTE de declaração judicial, assegurado à parte provar que não o realizou por JUSTA CAUSA (evento alheio à vontade da parte que a impediu de praticar o ato por si ou por mandatário). Verificada, o juiz permite o ato no prazo que lhe assinar." },
  { id: "cpc-37", lei: "CPC", ref: "CPC art. 224 · já caiu: 2010, 2014, 2015",
    frente: "Contagem de prazos (art. 224): início, vencimento, publicação.",
    verso: "Salvo disposição em contrário, os prazos são contados EXCLUINDO O DIA DO COMEÇO e INCLUINDO O DIA DO VENCIMENTO. Início e vencimento são protraídos para o primeiro dia útil seguinte quando o expediente forense encerrar antes ou iniciar depois do horário normal ou houver indisponibilidade da comunicação eletrônica (§1º). Data da PUBLICAÇÃO: o primeiro dia útil seguinte ao da DISPONIBILIZAÇÃO no Diário da Justiça eletrônico (§2º). A contagem tem início no primeiro dia útil que seguir ao da publicação (§3º)." },
  { id: "cpc-38", lei: "CPC", ref: "CPC art. 225",
    frente: "Renúncia ao prazo (art. 225).",
    verso: "A parte pode renunciar ao prazo estabelecido EXCLUSIVAMENTE em seu favor, desde que o faça de maneira EXPRESSA." },
  { id: "cpc-39", lei: "CPC", ref: "CPC art. 226 · já caiu: 2007",
    frente: "Prazos do juiz para despachos, decisões e sentenças (art. 226).",
    verso: "O juiz proferirá: I os DESPACHOS no prazo de 5 DIAS; II as DECISÕES INTERLOCUTÓRIAS em 10 DIAS; III as SENTENÇAS em 30 DIAS." },
  { id: "cpc-40", lei: "CPC", ref: "CPC art. 227",
    frente: "Prorrogação de prazos pelo juiz (art. 227).",
    verso: "Em qualquer grau de jurisdição, havendo MOTIVO JUSTIFICADO, o juiz pode exceder, por IGUAL TEMPO, os prazos a que está submetido." },
  { id: "cpc-41", lei: "CPC", ref: "CPC art. 228 · já caiu: 2013",
    frente: "Prazos do serventuário (art. 228): conclusão e atos processuais.",
    verso: "Incumbe ao serventuário remeter os autos CONCLUSOS no prazo de 1 (UM) DIA e executar os atos processuais no prazo de 5 (CINCO) DIAS, contados da data em que: I houver concluído o ato processual anterior, se imposto por lei; II tiver CIÊNCIA DA ORDEM, quando determinada pelo juiz. Ao receber os autos, certifica o DIA e a HORA da ciência (§1º). Nos autos eletrônicos, a juntada de petições ocorre de forma AUTOMÁTICA, independentemente de ato do serventuário (§2º)." },
  { id: "cpc-42", lei: "CPC", ref: "CPC art. 229",
    frente: "Prazo em dobro para litisconsortes com procuradores diferentes (art. 229).",
    verso: "Os litisconsortes com DIFERENTES procuradores, de ESCRITÓRIOS DISTINTOS, têm prazos contados em DOBRO para todas as manifestações, em qualquer juízo ou tribunal, independentemente de requerimento. Cessa a dobra se, havendo apenas 2 réus, só um deles apresenta defesa (§1º). NÃO se aplica aos processos em AUTOS ELETRÔNICOS (§2º)." },
  { id: "cpc-43", lei: "CPC", ref: "CPC art. 230",
    frente: "Início da contagem do prazo para parte, procurador, Advocacia Pública, Defensoria e MP (art. 230).",
    verso: "O prazo será contado da CITAÇÃO, da INTIMAÇÃO ou da NOTIFICAÇÃO." },
  { id: "cpc-44", lei: "CPC", ref: "CPC art. 231, I a IV · já caiu: 2023",
    frente: "Dia do começo do prazo: correio, oficial de justiça, escrivão e edital (art. 231, I a IV).",
    verso: "I citação ou intimação pelo CORREIO: data da JUNTADA aos autos do AVISO DE RECEBIMENTO; II por OFICIAL DE JUSTIÇA: data da JUNTADA do MANDADO cumprido; III por ato do ESCRIVÃO ou chefe de secretaria: data da OCORRÊNCIA; IV por EDITAL: o DIA ÚTIL SEGUINTE ao fim da dilação assinada pelo juiz." },
  { id: "cpc-45", lei: "CPC", ref: "CPC art. 231, V a IX",
    frente: "Dia do começo do prazo: eletrônica, carta, publicação, carga (art. 231, V a IX).",
    verso: "V citação ou intimação ELETRÔNICA: o dia útil seguinte à CONSULTA ao teor ou ao término do prazo para a consulta; VI em cumprimento de CARTA: data da juntada do COMUNICADO do art. 232 ou, não havendo, da CARTA cumprida aos autos de origem; VII intimação pelo DIÁRIO da Justiça impresso ou eletrônico: data da PUBLICAÇÃO; VIII por CARGA dos autos: o DIA DA CARGA; IX citação eletrônica: o QUINTO dia útil seguinte à confirmação do recebimento." },
  { id: "cpc-46", lei: "CPC", ref: "CPC art. 231, §§1º a 4º",
    frente: "Mais de um réu, mais de um intimado e ato praticado diretamente pela parte (art. 231, §§1º a 4º).",
    verso: "§1º: mais de um RÉU: o dia do começo do prazo para contestar é o da ÚLTIMA das datas dos incisos I a VI. §2º: mais de um INTIMADO: o prazo de cada um é contado INDIVIDUALMENTE. §3º: ato a ser praticado DIRETAMENTE pela parte, sem representante judicial: começa na data da COMUNICAÇÃO. §4º: o inciso II aplica-se à citação com HORA CERTA." },
  { id: "cpc-47", lei: "CPC", ref: "CPC art. 232",
    frente: "Citação ou intimação por carta: o que o juiz deprecado informa (art. 232).",
    verso: "Nos atos de comunicação por carta precatória, rogatória ou de ordem, a realização da citação ou intimação é IMEDIATAMENTE INFORMADA, por meio ELETRÔNICO, pelo juiz DEPRECADO ao juiz DEPRECANTE." },
  { id: "cpc-48", lei: "CPC", ref: "CPC art. 233",
    frente: "Verificação de prazos do serventuário (art. 233).",
    verso: "Incumbe ao JUIZ verificar se o serventuário excedeu, sem motivo legítimo, os prazos; constatada a falta, ORDENA a instauração de PROCESSO ADMINISTRATIVO (§1º). Qualquer das partes, o MP ou a Defensoria Pública pode REPRESENTAR ao juiz contra o serventuário (§2º)." },
  { id: "cpc-49", lei: "CPC", ref: "CPC art. 234",
    frente: "Restituição dos autos por advogados, defensor e MP (art. 234).",
    verso: "Devem restituir os autos NO PRAZO do ato a ser praticado. Qualquer interessado pode EXIGIR os autos do advogado que exceder o prazo (§1º). Intimado, o advogado que não devolver em 3 DIAS perde o direito à VISTA fora de cartório e incorre em MULTA de metade do salário mínimo (§2º). O juiz comunica à OAB para procedimento disciplinar e multa (§3º). Membro do MP, Defensoria ou Advocacia Pública: multa ao agente responsável (§4º) e comunicação ao órgão disciplinar (§5º)." },
  { id: "cpc-50", lei: "CPC", ref: "CPC art. 235 · caiu 2024 Q39",
    frente: "Representação contra juiz ou relator que excede prazo (art. 235).",
    verso: "Qualquer parte, o MP ou a Defensoria pode representar ao CORREGEDOR do tribunal ou ao CNJ. Ouvido previamente o juiz, não sendo arquivamento liminar, é instaurado procedimento, com intimação eletrônica para justificativa em 15 DIAS (§1º). Em até 48 HORAS após a justificativa, o corregedor determina a intimação para que, em 10 DIAS, PRATIQUE O ATO (§2º). MANTIDA a inércia, os autos vão ao SUBSTITUTO LEGAL para decisão em 10 DIAS (§3º). (Prazo para sentenciar: 30 dias, art. 226, III.)" },
  { id: "cpc-51", lei: "CPC", ref: "CPC art. 236",
    frente: "Cumprimento dos atos por ordem judicial e cartas (art. 236).",
    verso: "Os atos são cumpridos por ORDEM JUDICIAL. Expede-se CARTA para atos fora dos limites territoriais do tribunal, comarca, seção ou subseção (§1º). O tribunal pode expedir carta para juízo a ele vinculado quando o ato deva se realizar fora dos limites do local de sua sede (§2º). Admite-se a prática de atos por VIDEOCONFERÊNCIA ou recurso tecnológico de transmissão de sons e imagens em tempo real (§3º)." },
  { id: "cpc-52", lei: "CPC", ref: "CPC art. 237",
    frente: "Tipos de carta (art. 237).",
    verso: "I de ORDEM: expedida pelo TRIBUNAL ao juízo a ele vinculado (art. 236, §2º); II ROGATÓRIA: para órgão jurisdicional ESTRANGEIRO praticar ato de cooperação jurídica internacional; III PRECATÓRIA: para órgão jurisdicional brasileiro de competência territorial diversa; IV ARBITRAL: para o Judiciário praticar ato objeto de pedido do juízo arbitral, inclusive tutela provisória. Se o processo federal ou de tribunal superior exigir ato em local sem vara federal, a carta pode ser dirigida ao juízo ESTADUAL." },
  { id: "cpc-53", lei: "CPC", ref: "CPC arts. 238 e 239 · já caiu: 2006",
    frente: "Citação: conceito, prazo e validade do processo (arts. 238 e 239).",
    verso: "Art. 238: CITAÇÃO é o ato pelo qual são convocados o réu, o executado ou o interessado para integrar a relação processual; será efetivada em até 45 DIAS a partir da propositura da ação. Art. 239: para a validade do processo é INDISPENSÁVEL a citação, ressalvados o indeferimento da inicial e a improcedência liminar. O COMPARECIMENTO ESPONTÂNEO supre a falta ou nulidade da citação, fluindo desde então o prazo para contestação ou embargos (§1º). Rejeitada a alegação de nulidade: no conhecimento o réu é REVEL; na execução, o feito segue (§2º)." },
  { id: "cpc-54", lei: "CPC", ref: "CPC art. 240 · já caiu: 2006, 2007, 2011",
    frente: "Efeitos da citação válida (art. 240).",
    verso: "Ainda quando ordenada por juízo INCOMPETENTE, induz LITISPENDÊNCIA, torna LITIGIOSA a coisa e constitui em MORA o devedor (ressalvados os arts. 397 e 398 do CC). A interrupção da PRESCRIÇÃO pelo despacho que ordena a citação RETROAGE à data da PROPOSITURA (§1º). O autor deve adotar, em 10 DIAS, as providências para viabilizar a citação, sob pena de não se aplicar o §1º (§2º). A parte não é prejudicada pela demora imputável exclusivamente ao serviço judiciário (§3º). O efeito retroativo aplica-se à DECADÊNCIA e demais prazos extintivos (§4º)." },
  { id: "cpc-55", lei: "CPC", ref: "CPC art. 241",
    frente: "Comunicação do trânsito em julgado favorável ao réu antes da citação (art. 241).",
    verso: "Transitada em julgado a sentença de mérito proferida em favor do réu ANTES da citação, incumbe ao ESCRIVÃO ou chefe de secretaria COMUNICAR-LHE o resultado do julgamento." },
  { id: "cpc-56", lei: "CPC", ref: "CPC art. 242 · já caiu: 2006, 2010, 2011",
    frente: "Citação pessoal e possibilidade de citar mandatário, administrador e representante da Fazenda (art. 242).",
    verso: "A citação é PESSOAL, podendo ser feita na pessoa do REPRESENTANTE LEGAL ou do PROCURADOR do réu. Na AUSÊNCIA do citando, será feita na pessoa de seu MANDATÁRIO, ADMINISTRADOR, PREPOSTO ou GERENTE, quando a ação se originar de atos por eles praticados (§1º). LOCADOR ausente do Brasil sem deixar procurador: citado na pessoa do ADMINISTRADOR do imóvel encarregado de receber os aluguéis (§2º). União, Estados, DF, Municípios, autarquias e fundações de direito público: perante o órgão de ADVOCACIA PÚBLICA responsável pela representação judicial (§3º)." },
  { id: "cpc-57", lei: "CPC", ref: "CPC art. 243 · já caiu: 2011",
    frente: "Lugar da citação e citação do militar (art. 243).",
    verso: "A citação pode ser feita em QUALQUER LUGAR em que se encontre o réu, executado ou interessado. O MILITAR em serviço ativo será citado na UNIDADE em que estiver servindo, se não for conhecida sua residência ou nela não for encontrado." },
  { id: "cpc-58", lei: "CPC", ref: "CPC art. 244 · já caiu: 2006, 2010, 2011, 2021",
    frente: "Quando NÃO se fará citação (art. 244)?",
    verso: "SALVO para evitar o perecimento do direito: I de quem estiver participando de ATO DE CULTO RELIGIOSO; II de cônjuge, companheiro ou parente do morto (consanguíneo ou afim, em linha reta ou colateral em 2º GRAU), no dia do falecimento e nos 7 DIAS seguintes; III de NOIVOS, nos 3 PRIMEIROS DIAS seguintes ao casamento; IV de DOENTE, enquanto grave o seu estado." },
  { id: "cpc-59", lei: "CPC", ref: "CPC art. 245 · já caiu: 2006, 2010, 2021",
    frente: "Citando mentalmente incapaz ou impossibilitado de receber a citação (art. 245).",
    verso: "NÃO se faz citação. O oficial descreve e certifica minuciosamente a ocorrência (§1º). Para examinar o citando, o juiz nomeia MÉDICO, que apresenta laudo em 5 DIAS (§2º), dispensado se pessoa da família apresentar declaração do médico atestando a incapacidade (§3º). Reconhecida a impossibilidade, o juiz nomeia CURADOR ao citando, restringindo a nomeação à causa (§4º), e a citação é feita na pessoa do curador (§5º)." },
  { id: "cpc-60", lei: "CPC", ref: "CPC art. 246, caput e §1º",
    frente: "Citação preferencialmente por meio eletrônico (art. 246).",
    verso: "Será feita preferencialmente por meio ELETRÔNICO, no prazo de até 2 DIAS ÚTEIS, contado da decisão que a determinar, por meio dos endereços eletrônicos indicados pelo citando no banco de dados do Poder Judiciário (regulamento do CNJ). As empresas públicas e privadas são OBRIGADAS a manter cadastro nos sistemas de processo eletrônico para receber citações e intimações (§1º), aplicável à União, Estados, DF, Municípios e entidades da administração indireta (§2º)." },
  { id: "cpc-61", lei: "CPC", ref: "CPC art. 246, §§1º-A a 1º-C",
    frente: "Ausência de confirmação da citação eletrônica (art. 246, §§1º-A a 1º-C).",
    verso: "A AUSÊNCIA de confirmação em até 3 DIAS ÚTEIS do recebimento implica citação: I pelo CORREIO; II por OFICIAL DE JUSTIÇA; III pelo ESCRIVÃO ou chefe de secretaria, se o citando comparecer ao cartório; IV por EDITAL. Na primeira oportunidade de falar nos autos, o réu deve apresentar JUSTA CAUSA pela ausência de confirmação. Deixar de confirmar, sem justa causa, é ATO ATENTATÓRIO À DIGNIDADE DA JUSTIÇA, com multa de até 5% do valor da causa." },
  { id: "cpc-62", lei: "CPC", ref: "CPC art. 246, §§3º a 6º",
    frente: "Usucapião, citação por correio eletrônico e microempresas (art. 246, §§3º a 6º).",
    verso: "§3º: na ação de USUCAPIÃO de imóvel, os confinantes são citados PESSOALMENTE, exceto quando tiver por objeto unidade autônoma de prédio em condomínio. §4º: as citações por correio eletrônico vêm acompanhadas de orientações para a confirmação e de CÓDIGO IDENTIFICADOR. §5º: microempresas e pequenas empresas só se sujeitam à citação eletrônica obrigatória quando NÃO possuírem endereço eletrônico cadastrado na REDESIM. §6º: há compartilhamento de cadastro com o Judiciário, respeitado o sigilo fiscal e a proteção de dados." },
  { id: "cpc-63", lei: "CPC", ref: "CPC art. 247 · já caiu: 2006, 2010",
    frente: "Citação pelo correio ou meio eletrônico: quando NÃO se admite (art. 247)?",
    verso: "É admitida para qualquer comarca do País, EXCETO: I nas AÇÕES DE ESTADO (art. 695, §3º); II quando o citando for INCAPAZ; III quando for PESSOA DE DIREITO PÚBLICO; IV quando residir em local NÃO ATENDIDO pela entrega domiciliar de correspondência; V quando o autor, justificadamente, a requerer de outra forma." },
  { id: "cpc-64", lei: "CPC", ref: "CPC art. 248",
    frente: "Citação pelo correio (art. 248).",
    verso: "Deferida, o escrivão remete ao citando COPIAS da petição inicial e do despacho do juiz, comunica o prazo para resposta, o endereço do juízo e o cartório. A carta é REGISTRADA, exigindo o carteiro a assinatura do recibo (§1º). Pessoa jurídica: válida a entrega a pessoa com poderes de GERÊNCIA GERAL ou ADMINISTRAÇÃO ou a funcionário responsável pelo recebimento de correspondências (§2º). Condomínios edilícios ou loteamentos com controle de acesso: válida a entrega a funcionário da PORTARIA, que pode recusar se declarar por escrito que o destinatário está ausente (§4º)." },
  { id: "cpc-65", lei: "CPC", ref: "CPC art. 249",
    frente: "Citação por oficial de justiça (art. 249).",
    verso: "Será feita por oficial de justiça nas hipóteses previstas no Código ou em lei, ou quando FRUSTRADA a citação pelo correio." },
  { id: "cpc-66", lei: "CPC", ref: "CPC art. 250",
    frente: "Requisitos do mandado de citação (art. 250).",
    verso: "I os nomes do autor e do citando e seus domicílios ou residências; II a FINALIDADE da citação, com as especificações da inicial, e a menção do PRAZO para contestar, sob pena de REVELIA, ou para embargar a execução; III a aplicação de sanção para o caso de descumprimento, se houver; IV se for o caso, a intimação do citando para comparecer, ACOMPANHADO DE ADVOGADO ou defensor público, à audiência de CONCILIAÇÃO ou MEDIAÇÃO (dia, hora e lugar); V a CÓPIA da petição inicial, do despacho ou da decisão que deferir tutela provisória; VI a assinatura do escrivão ou chefe de secretaria e a declaração de que o subscreve POR ORDEM DO JUIZ." },
  { id: "cpc-67", lei: "CPC", ref: "CPC art. 251",
    frente: "O que o oficial de justiça faz ao encontrar o citando (art. 251).",
    verso: "Procura o citando e, onde o encontrar, o cita: I LENDO-LHE o mandado e entregando-lhe a CONTRAFÉ; II portando por FÉ se recebeu ou recusou a contrafé; III obtendo a NOTA DE CIENTE ou certificando que o citando não a apôs no mandado." },
  { id: "cpc-68", lei: "CPC", ref: "CPC arts. 252 a 255 · já caiu: 2010",
    frente: "Citação com hora certa (arts. 252 a 255).",
    verso: "Art. 252: por 2 VEZES procurado o citando sem ser encontrado, havendo SUSPEITA DE OCULTAÇÃO, o oficial intima qualquer pessoa da família ou, em sua falta, qualquer VIZINHO de que voltará no DIA ÚTIL IMEDIATO, na hora que designar (em condomínio, basta o funcionário da portaria). Art. 253: no dia e hora, INDEPENDENTEMENTE de novo despacho, o oficial comparece e, se o citando não estiver presente, dá por feita a citação, ainda que ele se tenha ocultado em outra comarca; é efetivada mesmo que a pessoa da família ou o vizinho esteja ausente ou se recuse a receber (§2º); deixa CONTRAFÉ (§3º) e adverte que será nomeado CURADOR ESPECIAL se houver REVELIA (§4º). Art. 254: o escrivão envia ao réu, em 10 DIAS da juntada do mandado, carta, telegrama ou correspondência eletrônica. Art. 255: em comarcas CONTÍGUAS de fácil comunicação e na mesma REGIÃO METROPOLITANA, o oficial pode efetuar citações, intimações, notificações, penhoras e atos executivos em qualquer delas." },
  { id: "cpc-69", lei: "CPC", ref: "CPC art. 256 · já caiu: 2010",
    frente: "Quando se faz a citação por edital (art. 256)?",
    verso: "I quando DESCONHECIDO ou INCERTO o citando; II quando IGNORADO, INCERTO ou INACESSÍVEL o lugar em que se encontra; III nos casos expressos em lei. Considera-se INACESSÍVEL o país que recusar o cumprimento de CARTA ROGATÓRIA (§1º); se inacessível, a notícia é divulgada também pelo RÁDIO, se houver emissora na comarca (§2º). O réu está em local ignorado se infrutíferas as tentativas de localização, inclusive mediante requisição de informações a órgãos públicos ou concessionárias (§3º)." },
  { id: "cpc-70", lei: "CPC", ref: "CPC arts. 257 a 259",
    frente: "Requisitos do edital, multa e editais obrigatórios (arts. 257 a 259).",
    verso: "Art. 257: I afirmação do autor ou certidão do oficial das circunstâncias autorizadoras; II PUBLICAÇÃO na rede mundial de computadores, no site do tribunal e na plataforma de editais do CNJ, certificada nos autos; III prazo fixado pelo juiz entre 20 e 60 DIAS, fluindo da publicação única ou da primeira; IV advertência de que será nomeado CURADOR ESPECIAL em caso de revelia. O juiz pode determinar publicação também em jornal local. Art. 258: quem requerer edital alegando DOLOSAMENTE as circunstâncias incorre em MULTA de 5 SALÁRIOS MÍNIMOS, revertida em benefício do citando. Art. 259: editais na USUCAPIÃO de imóvel, na recuperação ou substituição de título ao PORTADOR e em ações em que se exija a provocação de interessados incertos ou desconhecidos." },
  { id: "cpc-71", lei: "CPC", ref: "CPC art. 260",
    frente: "Requisitos das cartas de ordem, precatória e rogatória (art. 260).",
    verso: "I a indicação dos JUÍZES de origem e de cumprimento; II o INTEIRO TEOR da petição, do despacho judicial e do instrumento do MANDATO; III a menção do ATO processual que constitui o objeto; IV o encerramento com a ASSINATURA DO JUIZ. Quaisquer outras peças são trasladadas e mapa, desenho ou gráfico, se necessários (§1º). Exame pericial sobre documento: remetido o ORIGINAL, ficando nos autos reprodução fotográfica (§2º). Carta arbitral: instruída com a CONVENÇÃO DE ARBITRAGEM e provas da nomeação do árbitro e de sua aceitação (§3º)." },
  { id: "cpc-72", lei: "CPC", ref: "CPC arts. 261 e 262",
    frente: "Prazo, intimação das partes e caráter itinerante da carta (arts. 261 e 262).",
    verso: "Art. 261: em todas as cartas o juiz fixa o PRAZO para cumprimento. As partes são intimadas do ATO DE EXPEDIÇÃO e acompanham o cumprimento no juízo destinatário, a quem compete os atos de comunicação; a parte interessada coopera. Art. 262: a carta tem caráter ITINERANTE: antes ou depois de ordenado o cumprimento, pode ser encaminhada a juízo diverso do que dela consta; o encaminhamento é imediatamente comunicado ao órgão expedidor, que intima as partes." },
  { id: "cpc-73", lei: "CPC", ref: "CPC arts. 263 a 266",
    frente: "Cartas por meio eletrônico, telefone ou telegrama (arts. 263 a 266).",
    verso: "Art. 263: as cartas são expedidas preferencialmente por meio ELETRÔNICO, com assinatura eletrônica do juiz. Art. 264: a carta de ordem e a precatória por meio eletrônico, telefone ou telegrama contêm, em RESUMO SUBSTANCIAL, os requisitos do art. 250, especialmente a aferição da AUTENTICIDADE. Art. 265: o secretário do tribunal, escrivão ou chefe de secretaria do juízo deprecante transmite por telefone ao juízo de cumprimento, por intermédio do escrivão do PRIMEIRO OFÍCIO da PRIMEIRA VARA; no mesmo dia ou no dia útil imediato, o escrivão deprecado telefona ou envia mensagem eletrônica para CONFIRMAÇÃO (§1º); confirmada, submete a carta a despacho (§2º). Art. 266: os atos requisitados por meio eletrônico e telegrama são praticados de OFÍCIO, devendo a parte DEPOSITAR as despesas." },
  { id: "cpc-74", lei: "CPC", ref: "CPC arts. 267 e 268",
    frente: "Quando o juiz recusa cumprimento à carta precatória ou arbitral e prazo de devolução (arts. 267 e 268).",
    verso: "Art. 267: recusa, devolvendo com DECISÃO MOTIVADA, quando: I a carta não estiver revestida dos REQUISITOS legais; II faltar ao juiz competência em razão da MATÉRIA ou da HIERARQUIA; III tiver DÚVIDA acerca de sua AUTENTICIDADE. No caso do inciso II, o deprecado pode remeter a carta ao juiz ou tribunal competente. Art. 268: cumprida, a carta é devolvida ao juízo de origem em 10 DIAS, independentemente de traslado, pagas as custas pela parte." },
  { id: "cpc-75", lei: "CPC", ref: "CPC art. 269",
    frente: "Intimação (art. 269): conceito e intimação pelo advogado.",
    verso: "INTIMAÇÃO é o ato pelo qual se dá CIÊNCIA a alguém dos atos e termos do processo. Os advogados podem promover a intimação do advogado da outra parte pelo CORREIO, juntando aos autos cópia do ofício e do aviso de recebimento (§1º), instruído com cópia do despacho, decisão ou sentença (§2º). A intimação da União, Estados, DF, Municípios, autarquias e fundações públicas é feita perante o órgão de ADVOCACIA PÚBLICA (§3º)." },
  { id: "cpc-76", lei: "CPC", ref: "CPC arts. 270 a 272 · já caiu: 2015, 2017",
    frente: "Intimações: meio eletrônico, de ofício e publicação no órgão oficial (arts. 270 a 272).",
    verso: "Art. 270: realizam-se, sempre que possível, por meio ELETRÔNICO; aplica-se ao MP, à Defensoria e à Advocacia Pública o art. 246, §1º. Art. 271: o juiz determina DE OFÍCIO as intimações em processos pendentes. Art. 272: quando não eletrônicas, consideram-se feitas pela PUBLICAÇÃO no órgão oficial. Sob pena de NULIDADE, da publicação constam os nomes das partes e de seus advogados com o número de inscrição na OAB, ou da sociedade de advogados; os nomes das partes sem ABREVIATURAS; os dos advogados completos e iguais aos da procuração ou registro na OAB. Pedido expresso para intimações em nome de advogado indicado: o desatendimento gera nulidade (§5º)." },
  { id: "cpc-77", lei: "CPC", ref: "CPC art. 272, §§6º a 9º",
    frente: "Carga dos autos, credenciamento e nulidade da intimação (art. 272, §§6º a 9º).",
    verso: "§6º: a retirada dos autos EM CARGA pelo advogado, por pessoa credenciada, pela Advocacia Pública, Defensoria ou MP implica INTIMAÇÃO de qualquer decisão contida no processo, ainda que pendente de publicação. §7º: o advogado ou a sociedade deve requerer o CREDENCIAMENTO para retirada por preposto. §8º: a parte argui a nulidade da intimação em CAPÍTULO PRELIMINAR do próprio ato que lhe caiba praticar, tido por tempestivo se o vício for reconhecido. §9º: se for impossível a prática imediata do ato por falta de acesso aos autos, limita-se a arguir a nulidade, e o prazo conta da intimação da decisão que a reconheça." },
  { id: "cpc-78", lei: "CPC", ref: "CPC arts. 273 a 275",
    frente: "Intimação pelo escrivão, pelo correio e por oficial de justiça (arts. 273 a 275).",
    verso: "Art. 273: se inviável a intimação eletrônica e não houver publicação em órgão oficial, o escrivão intima os advogados PESSOALMENTE, se domiciliados na sede do juízo, ou por CARTA REGISTRADA com AR, se domiciliados fora. Art. 274: sem outra regra, as intimações são feitas pelo CORREIO ou, se presentes em cartório, diretamente pelo escrivão; presumem-se VÁLIDAS as dirigidas ao endereço constante dos autos, ainda que não recebidas pessoalmente, se a mudança não foi comunicada ao juízo. Art. 275: por OFICIAL DE JUSTIÇA quando frustrada a eletrônica ou pelo correio; a certidão contém o lugar e a descrição da pessoa intimada (documento de identidade), a declaração de entrega da CONTRAFÉ e a NOTA DE CIENTE ou certidão de que não a apôs; se necessário, hora certa ou edital." },
  { id: "cpc-79", lei: "CPC", ref: "CPC arts. 294 a 296",
    frente: "Tutela provisória: fundamentos, custas e eficácia (arts. 294 a 296).",
    verso: "Art. 294: pode fundamentar-se em URGÊNCIA ou EVIDÊNCIA; a tutela de urgência, cautelar ou antecipada, pode ser concedida em caráter ANTECEDENTE ou INCIDENTAL. Art. 295: a tutela requerida em caráter INCIDENTAL independe do pagamento de CUSTAS. Art. 296: conserva a eficácia na pendência do processo, mas pode, a qualquer tempo, ser REVOGADA ou MODIFICADA; mantém a eficácia durante a SUSPENSÃO do processo, salvo decisão em contrário." },
  { id: "cpc-80", lei: "CPC", ref: "CPC arts. 297 a 299",
    frente: "Efetivação, motivação e competência da tutela provisória (arts. 297 a 299).",
    verso: "Art. 297: o juiz pode determinar as medidas adequadas para efetivação, observadas as normas do CUMPRIMENTO PROVISÓRIO da sentença. Art. 298: na decisão que conceder, negar, modificar ou revogar, o juiz MOTIVA seu convencimento de modo CLARO e PRECISO. Art. 299: requerida ao JUÍZO DA CAUSA e, quando antecedente, ao juízo competente para conhecer do PEDIDO PRINCIPAL; nas ações de competência originária de tribunal e nos recursos, ao órgão competente para apreciar o MÉRITO." },
  { id: "cpc-81", lei: "CPC", ref: "CPC art. 300 · já caiu: 2023",
    frente: "Tutela de urgência (art. 300): requisitos, caução e irreversibilidade.",
    verso: "Concede-se quando houver elementos que evidenciem a PROBABILIDADE DO DIREITO e o PERIGO DE DANO ou o RISCO AO RESULTADO ÚTIL do processo. O juiz pode exigir CAUÇÃO real ou fidejussória idônea, DISPENSADA se a parte economicamente hipossuficiente não puder oferecê-la (§1º). Pode ser concedida LIMINARMENTE ou após JUSTIFICAÇÃO prévia (§2º). A tutela antecipada NÃO será concedida quando houver perigo de IRREVERSIBILIDADE dos efeitos da decisão (§3º)." },
  { id: "cpc-82", lei: "CPC", ref: "CPC arts. 301 e 302",
    frente: "Medidas da tutela cautelar e responsabilidade pelo prejuízo (arts. 301 e 302).",
    verso: "Art. 301: a cautelar pode ser efetivada mediante ARRESTO, SEQUESTRO, ARROLAMENTO DE BENS, REGISTRO DE PROTESTO contra alienação de bem e qualquer outra medida idônea. Art. 302: a parte responde pelo prejuízo que a efetivação causar ao adversário se: I a sentença lhe for DESFAVORÁVEL; II obtida liminarmente em caráter antecedente, NÃO fornecer os meios para a citação do requerido em 5 DIAS; III cessar a eficácia da medida em qualquer hipótese legal; IV o juiz acolher decadência ou prescrição. A indenização é liquidada nos mesmos autos, sempre que possível." },
  { id: "cpc-83", lei: "CPC", ref: "CPC art. 303, caput e §1º · já caiu: 2018, 2023",
    frente: "Tutela antecipada requerida em caráter ANTECEDENTE (art. 303): petição e consequências da concessão.",
    verso: "Quando a urgência for contemporânea à propositura, a petição inicial pode limitar-se ao REQUERIMENTO da tutela antecipada e à indicação do pedido de TUTELA FINAL, com a exposição da lide, do direito e do perigo de dano. Concedida a tutela: I o autor ADITA a inicial, em 15 DIAS (ou prazo maior fixado), complementando a argumentação, juntando novos documentos e confirmando o pedido de tutela final; II o réu é citado e intimado para a audiência de CONCILIAÇÃO ou MEDIAÇÃO (art. 334); III não havendo autocomposição, o prazo de contestação segue o art. 335." },
  { id: "cpc-84", lei: "CPC", ref: "CPC art. 303, §§2º a 6º · já caiu: 2023",
    frente: "Aditamento, valor da causa e emenda na tutela antecedente (art. 303, §§2º a 6º).",
    verso: "§2º: não realizado o aditamento, o processo é EXTINTO sem resolução do mérito. §3º: o aditamento ocorre nos MESMOS AUTOS, SEM novas custas. §4º: o autor indica o VALOR DA CAUSA, considerando o pedido de tutela final. §5º: o autor indica na inicial que pretende valer-se do benefício. §6º: se o juiz entender que não há elementos para a tutela antecipada, determina a EMENDA da inicial em até 5 DIAS, sob pena de indeferimento e extinção sem resolução do mérito." },
  { id: "cpc-85", lei: "CPC", ref: "CPC art. 304 · já caiu: 2018",
    frente: "Estabilização da tutela antecipada antecedente (art. 304).",
    verso: "A tutela antecipada concedida nos termos do art. 303 TORNA-SE ESTÁVEL se da decisão que a conceder NÃO for interposto o respectivo RECURSO, e o processo é EXTINTO (§1º). Qualquer das partes pode demandar a outra para REVER, REFORMAR ou INVALIDAR a tutela estabilizada (§2º); ela conserva os efeitos enquanto não revista por decisão de mérito (§3º). Pode-se requerer o DESARQUIVAMENTO dos autos, e fica PREVENTO o juízo (§4º). O direito de rever EXTINGUE-SE em 2 (DOIS) ANOS, contados da ciência da decisão que extinguiu o processo (§5º). A decisão NÃO faz COISA JULGADA (§6º)." },
  { id: "cpc-86", lei: "CPC", ref: "CPC arts. 305 a 307",
    frente: "Tutela cautelar antecedente: petição, citação e revelia (arts. 305 a 307).",
    verso: "Art. 305: a petição indica a LIDE e seu fundamento, a exposição sumária do direito a assegurar e o PERIGO DE DANO ou risco ao resultado útil; se o pedido tiver natureza ANTECIPADA, o juiz observa o art. 303. Art. 306: o réu é citado para, em 5 DIAS, CONTESTAR e indicar as provas. Art. 307: não contestado, os fatos presumem-se ACEITOS e o juiz decide em 5 DIAS; contestado, segue o PROCEDIMENTO COMUM." },
  { id: "cpc-87", lei: "CPC", ref: "CPC art. 308 · já caiu: 2021",
    frente: "Pedido principal após a tutela cautelar efetivada (art. 308).",
    verso: "Efetivada a cautelar, o pedido principal deve ser formulado em 30 DIAS, nos MESMOS autos, SEM novas custas. Pode ser formulado conjuntamente com o pedido cautelar (§1º). A causa de pedir pode ser ADITADA ao formular o pedido principal (§2º). Apresentado o pedido principal, as partes são intimadas para a audiência de conciliação ou mediação por seus advogados ou pessoalmente, SEM nova citação (§3º). Sem autocomposição, o prazo de contestação segue o art. 335 (§4º)." },
  { id: "cpc-88", lei: "CPC", ref: "CPC arts. 309 e 310 · já caiu: 2021",
    frente: "Cessação da eficácia da tutela antecedente e indeferimento da cautelar (arts. 309 e 310).",
    verso: "Art. 309: CESSA a eficácia se: I o autor não deduzir o pedido principal no prazo legal; II não for efetivada em 30 DIAS; III o juiz julgar IMPROCEDENTE o pedido principal ou extinguir o processo sem resolução do mérito. Se cessar, é VEDADO renovar o pedido, salvo sob NOVO FUNDAMENTO. Art. 310: o INDEFERIMENTO da cautelar não obsta o pedido principal nem influi no seu julgamento, SALVO se o motivo for o reconhecimento de DECADÊNCIA ou PRESCRIÇÃO." },
  { id: "cpc-89", lei: "CPC", ref: "CPC art. 311 · caiu 2024 Q40 · já caiu: 2017",
    frente: "Tutela da EVIDÊNCIA (art. 311): hipóteses.",
    verso: "Concedida INDEPENDENTEMENTE de perigo de dano ou risco ao resultado útil, quando: I ficar caracterizado ABUSO DO DIREITO DE DEFESA ou manifesto propósito PROTELATÓRIO; II as alegações de fato puderem ser comprovadas APENAS DOCUMENTALMENTE e houver TESE firmada em casos repetitivos ou SÚMULA VINCULANTE; III pedido REIPERSECUTÓRIO fundado em prova documental do CONTRATO DE DEPÓSITO (ordem de entrega do objeto sob multa); IV a inicial for instruída com PROVA DOCUMENTAL suficiente dos fatos constitutivos do direito do autor, a que o réu NÃO oponha prova capaz de gerar DÚVIDA RAZOÁVEL. Nos incisos II e III, o juiz pode decidir LIMINARMENTE." },
  { id: "cpc-90", lei: "CPC", ref: "CPC art. 318",
    frente: "Procedimento comum (art. 318).",
    verso: "Aplica-se a TODAS as causas, salvo disposição em contrário do Código ou de lei. Aplica-se SUBSIDIARIAMENTE aos demais procedimentos especiais e ao processo de execução." },
  { id: "cpc-91", lei: "CPC", ref: "CPC art. 319",
    frente: "Requisitos da petição inicial (art. 319).",
    verso: "Indicará: I o JUÍZO a que é dirigida; II nomes, prenomes, estado civil, existência de UNIÃO ESTÁVEL, profissão, CPF ou CNPJ, ENDEREÇO ELETRÔNICO, domicílio e residência do autor e do réu; III o FATO e os FUNDAMENTOS JURÍDICOS do pedido; IV o PEDIDO com suas especificações; V o VALOR DA CAUSA; VI as PROVAS; VII a OPÇÃO do autor pela realização ou não de AUDIÊNCIA DE CONCILIAÇÃO OU MEDIAÇÃO." },
  { id: "cpc-92", lei: "CPC", ref: "CPC art. 319, §§1º a 3º",
    frente: "Falta de informações do inciso II do art. 319: a inicial é indeferida?",
    verso: "§1º: o autor pode, na inicial, requerer ao juiz diligências para obter as informações. §2º: a inicial NÃO é indeferida se, a despeito da falta, for possível a CITAÇÃO do réu. §3º: não é indeferida se a obtenção das informações tornar IMPOSSÍVEL ou EXCESSIVAMENTE ONEROSO o acesso à justiça." },
  { id: "cpc-93", lei: "CPC", ref: "CPC arts. 320 e 321 · já caiu: 2006, 2010",
    frente: "Documentos indispensáveis e emenda da inicial (arts. 320 e 321).",
    verso: "Art. 320: a inicial é instruída com os DOCUMENTOS INDISPENSÁVEIS à propositura da ação. Art. 321: o juiz, ao verificar que a inicial não preenche os arts. 319 e 320 ou tem defeitos capazes de dificultar o julgamento de mérito, determina que o autor, no prazo de 15 DIAS, a EMENDE ou complete, indicando com PRECISÃO o que deve ser corrigido. Se o autor não cumprir, o juiz INDEFERE a petição inicial." },
  { id: "cpc-94", lei: "CPC", ref: "CPC art. 322 · já caiu: 2015, 2021",
    frente: "O pedido deve ser certo (art. 322).",
    verso: "O pedido deve ser CERTO. No principal compreendem-se os JUROS LEGAIS, a CORREÇÃO MONETÁRIA e as verbas de SUCUMBÊNCIA, inclusive HONORÁRIOS (§1º). A interpretação considera o CONJUNTO da postulação e observa o princípio da BOA-FÉ (§2º)." },
  { id: "cpc-95", lei: "CPC", ref: "CPC art. 323 · já caiu: 2021",
    frente: "Obrigação em prestações sucessivas (art. 323).",
    verso: "As prestações sucessivas são consideradas INCLUÍDAS no pedido, independentemente de declaração expressa do autor, e INCLUÍDAS na condenação, enquanto durar a obrigação, se o devedor, no curso do processo, deixar de pagá-las ou de consigná-las." },
  { id: "cpc-96", lei: "CPC", ref: "CPC art. 324",
    frente: "O pedido deve ser determinado: quando é lícito o pedido genérico (art. 324)?",
    verso: "I nas AÇÕES UNIVERSAIS, se o autor não puder individuar os bens demandados; II quando não for possível determinar, desde logo, as CONSEQUÊNCIAS do ato ou do fato; III quando a determinação do objeto ou do valor da condenação depender de ATO que deva ser praticado pelo RÉU. Aplica-se à RECONVENÇÃO (§2º)." },
  { id: "cpc-97", lei: "CPC", ref: "CPC arts. 325 a 328 · já caiu: 2011, 2015, 2021",
    frente: "Pedido alternativo, subsidiário e cumulação de pedidos (arts. 325 a 328).",
    verso: "Art. 325: ALTERNATIVO quando, pela natureza da obrigação, o devedor puder cumprir a prestação de mais de um modo; se a escolha couber ao devedor, o juiz assegura o direito de cumprir de um ou outro modo. Art. 326: é lícito formular pedidos em ORDEM SUBSIDIÁRIA (o juiz conhece do posterior se não acolher o anterior) e, alternativamente, para que o juiz acolha um deles. Art. 327: é lícita a CUMULAÇÃO, contra o mesmo réu, de vários pedidos, ainda que não haja conexão; requisitos: pedidos COMPATÍVEIS, MESMO JUÍZO COMPETENTE e procedimento ADEQUADO a todos. Art. 328: obrigação indivisível com pluralidade de credores: quem não participou recebe sua parte, deduzidas as despesas proporcionalmente." },
  { id: "cpc-98", lei: "CPC", ref: "CPC art. 329 · já caiu: 2011, 2014, 2015, 2021",
    frente: "Alteração do pedido e da causa de pedir pelo autor (art. 329).",
    verso: "O autor pode: I ATÉ A CITAÇÃO, aditar ou alterar o pedido ou a causa de pedir, INDEPENDENTEMENTE de consentimento do réu; II ATÉ O SANEAMENTO, aditar ou alterar o pedido e a causa de pedir, COM CONSENTIMENTO do réu, assegurado o contraditório em prazo mínimo de 15 DIAS, facultado o requerimento de prova suplementar. Aplica-se à reconvenção e à respectiva causa de pedir." },
  { id: "cpc-99", lei: "CPC", ref: "CPC art. 330 · já caiu: 2018",
    frente: "Indeferimento da petição inicial (art. 330): hipóteses e inépcia.",
    verso: "Será indeferida quando: I for INEPTA; II a parte for manifestamente ILEGÍTIMA; III o autor carecer de INTERESSE PROCESSUAL; IV não atendidas as prescrições dos arts. 106 e 321. É INEPTA quando: I faltar PEDIDO ou CAUSA DE PEDIR; II o pedido for INDETERMINADO (ressalvados os casos legais de pedido genérico); III da narração dos fatos não decorrer logicamente a CONCLUSÃO; IV contiver pedidos INCOMPATÍVEIS entre si." },
  { id: "cpc-100", lei: "CPC", ref: "CPC art. 330, §§2º e 3º",
    frente: "Ação de revisão de empréstimo, financiamento ou alienação de bens: o que o autor deve fazer?",
    verso: "Sob pena de INÉPCIA, o autor deve DISCRIMINAR na inicial, dentre as obrigações contratuais, aquelas que pretende CONTROVERTER, além de QUANTIFICAR o valor INCONTROVERSO do débito. O valor incontroverso deve CONTINUAR A SER PAGO no tempo e modo contratados." },
  { id: "cpc-101", lei: "CPC", ref: "CPC art. 331",
    frente: "Apelação contra o indeferimento da inicial e retratação (art. 331).",
    verso: "Indeferida a inicial, o autor pode APELAR, facultado ao juiz, em 5 DIAS, RETRATAR-SE. Não havendo retratação, manda CITAR o réu para responder ao recurso (§1º). Reformada a sentença, o prazo da contestação começa da intimação do retorno dos autos (§2º). Não interposta a apelação, o réu é INTIMADO do trânsito em julgado (§3º)." },
  { id: "cpc-102", lei: "CPC", ref: "CPC art. 332 · já caiu: 2018",
    frente: "Improcedência liminar do pedido (art. 332).",
    verso: "Nas causas que dispensem a FASE INSTRUTÓRIA, o juiz, independentemente da citação, julga liminarmente improcedente o pedido que contrariar: I súmula do STF ou STJ; II acórdão do STF ou STJ em recursos REPETITIVOS; III entendimento firmado em IRDR ou assunção de COMPETÊNCIA; IV súmula de tribunal de justiça sobre DIREITO LOCAL. Também pode julgar liminarmente improcedente se verificar DECADÊNCIA ou PRESCRIÇÃO (§1º). Interposta a apelação, o juiz pode RETRATAR-SE em 5 DIAS (§3º); sem retratação, cita o réu para CONTRARRAZÕES em 15 DIAS (§4º)." },
  { id: "cpc-103", lei: "CPC", ref: "CPC art. 334, caput a §3º",
    frente: "Audiência de conciliação ou mediação (art. 334): antecedências e sessões.",
    verso: "O juiz designa a audiência com antecedência mínima de 30 DIAS, devendo ser citado o réu com pelo menos 20 DIAS de antecedência. Conciliador ou mediador, onde houver, atua necessariamente (§1º). Pode haver mais de uma sessão, sem exceder 2 MESES da primeira (§2º). A intimação do autor é na pessoa de seu ADVOGADO (§3º)." },
  { id: "cpc-104", lei: "CPC", ref: "CPC art. 334, §§4º a 6º",
    frente: "Quando a audiência de conciliação NÃO é realizada (art. 334, §§4º a 6º).",
    verso: "§4º: I se AMBAS as partes manifestarem, expressamente, DESINTERESSE na composição; II quando NÃO se admitir autocomposição. §5º: o AUTOR indica o desinteresse na INICIAL; o RÉU, por petição, com 10 DIAS de antecedência da data da audiência. §6º: havendo LITISCONSÓRCIO, o desinteresse deve ser manifestado por TODOS os litisconsortes." },
  { id: "cpc-105", lei: "CPC", ref: "CPC art. 334, §§7º a 12",
    frente: "Audiência de conciliação: meio eletrônico, falta, advogado, procurador e pauta (art. 334, §§7º a 12).",
    verso: "§7º: pode realizar-se por meio ELETRÔNICO. §8º: o não comparecimento injustificado do autor ou do réu é ATO ATENTATÓRIO À DIGNIDADE DA JUSTIÇA, com multa de até 2% da vantagem econômica pretendida ou do valor da causa, revertida à União ou ao Estado. §9º: as partes devem estar acompanhadas de ADVOGADOS ou defensores públicos. §10: a parte pode constituir representante com procuração ESPECÍFICA, com poderes para negociar e transigir. §11: a autocomposição é reduzida a TERMO e HOMOLOGADA por sentença. §12: a pauta respeita o intervalo mínimo de 20 MINUTOS entre o início de uma e o início da seguinte." },
  { id: "cpc-106", lei: "CPC", ref: "CPC art. 335",
    frente: "Contestação (art. 335): prazo e termo inicial.",
    verso: "O réu pode oferecer contestação, por petição, em 15 DIAS, cujo termo inicial é a data: I da AUDIÊNCIA de conciliação ou mediação, ou da última sessão, quando qualquer parte não comparecer ou, comparecendo, não houver autocomposição; II do PROTOCOLO do pedido de CANCELAMENTO da audiência apresentado pelo réu (art. 334, §4º, I); III prevista no art. 231, conforme o modo da citação, nos DEMAIS casos. Litisconsórcio passivo e cancelamento: para cada réu, a data de seu pedido (§1º)." },
  { id: "cpc-107", lei: "CPC", ref: "CPC art. 336 · já caiu: 2006, 2010",
    frente: "Princípio da eventualidade na contestação (art. 336).",
    verso: "Incumbe ao réu alegar, na contestação, TODA a matéria de defesa, expondo as razões de FATO e de DIREITO com que impugna o pedido e especificando as PROVAS que pretende produzir." },
  { id: "cpc-108", lei: "CPC", ref: "CPC art. 337, I a XIII",
    frente: "Preliminares da contestação (art. 337): o que o réu alega ANTES de discutir o mérito?",
    verso: "I inexistência ou nulidade da CITAÇÃO; II incompetência ABSOLUTA e RELATIVA; III incorreção do VALOR DA CAUSA; IV INÉPCIA da inicial; V PEREMPÇÃO; VI LITISPENDÊNCIA; VII COISA JULGADA; VIII CONEXÃO; IX INCAPACIDADE da parte, defeito de representação ou falta de autorização; X CONVENÇÃO DE ARBITRAGEM; XI AUSÊNCIA DE LEGITIMIDADE ou de interesse processual; XII falta de CAUÇÃO ou de outra prestação exigida como preliminar; XIII indevida concessão do benefício de GRATUIDADE DE JUSTIÇA." },
  { id: "cpc-109", lei: "CPC", ref: "CPC art. 337, §§1º a 6º",
    frente: "Litispendência, coisa julgada e matérias conhecidas de ofício (art. 337, §§1º a 6º).",
    verso: "Ação IDÊNTICA: mesmas PARTES, mesma CAUSA DE PEDIR e mesmo PEDIDO. LITISPENDÊNCIA: repete-se ação que está EM CURSO. COISA JULGADA: repete-se ação já decidida por decisão TRANSITADA EM JULGADO. O juiz conhece de OFÍCIO as matérias do artigo, EXCETUADAS a CONVENÇÃO DE ARBITRAGEM e a INCOMPETÊNCIA RELATIVA (§5º). A ausência de alegação da arbitragem implica ACEITAÇÃO da jurisdição estatal e RENÚNCIA ao juízo arbitral (§6º)." },
  { id: "cpc-110", lei: "CPC", ref: "CPC arts. 338 e 339",
    frente: "Alegação de ilegitimidade pelo réu (arts. 338 e 339).",
    verso: "Art. 338: alegando o réu ser parte ILEGÍTIMA ou não ser o responsável pelo prejuízo, o juiz faculta ao autor, em 15 DIAS, alterar a inicial para SUBSTITUIÇÃO do réu; realizada, o autor reembolsa as despesas e paga honorários ao procurador do réu excluído, entre 3% e 5% do valor da causa (ou art. 85, §8º, se irrisório). Art. 339: o réu que alega ilegitimidade deve INDICAR o sujeito passivo da relação sempre que tiver conhecimento, sob pena de arcar com as despesas e indenizar o autor; o autor, em 15 DIAS, procede à substituição (§1º) ou pode optar por incluir o sujeito indicado como LITISCONSORTE passivo (§2º)." },
  { id: "cpc-111", lei: "CPC", ref: "CPC art. 340",
    frente: "Contestação com alegação de incompetência: onde pode ser protocolada (art. 340).",
    verso: "Havendo alegação de incompetência RELATIVA ou ABSOLUTA, a contestação pode ser protocolada no FORO DE DOMICÍLIO DO RÉU, fato imediatamente comunicado ao juiz da causa (preferencialmente por meio eletrônico). Segue livre distribuição ou, se citado por precatória, juntada à precatória (§1º). Reconhecida a competência do foro indicado, o juízo é PREVENTO (§2º). Alegada a incompetência, SUSPENDE-SE a audiência de conciliação (§3º), e o juízo competente designa nova data (§4º)." },
  { id: "cpc-112", lei: "CPC", ref: "CPC art. 341",
    frente: "Ônus da impugnação especificada (art. 341): quando os fatos não impugnados NÃO se presumem verdadeiros?",
    verso: "Incumbe ao réu manifestar-se PRECISAMENTE sobre as alegações de fato, presumindo-se verdadeiras as não impugnadas, SALVO se: I não for admissível a CONFISSÃO; II a inicial não estiver acompanhada de INSTRUMENTO que a lei considere da SUBSTÂNCIA do ato; III estiverem em CONTRADIÇÃO com a defesa, em seu conjunto. O ônus NÃO se aplica ao DEFENSOR PÚBLICO, ao ADVOGADO DATIVO e ao CURADOR ESPECIAL." },
  { id: "cpc-113", lei: "CPC", ref: "CPC art. 342",
    frente: "Novas alegações depois da contestação (art. 342).",
    verso: "Só é lícito ao réu deduzir novas alegações quando: I relativas a DIREITO ou FATO SUPERVENIENTE; II competir ao juiz conhecer delas de OFÍCIO; III por expressa autorização legal, puderem ser formuladas em QUALQUER TEMPO e grau de jurisdição." },
  { id: "cpc-114", lei: "CPC", ref: "CPC art. 343 · já caiu: 2007, 2010",
    frente: "Reconvenção (art. 343).",
    verso: "Na CONTESTAÇÃO, o réu pode propor reconvenção para manifestar pretensão própria, CONEXA com a ação principal ou com o fundamento da defesa. O autor é intimado, na pessoa de seu ADVOGADO, para responder em 15 DIAS (§1º). A desistência da ação ou causa extintiva que impeça o exame do mérito NÃO obsta o prosseguimento quanto à reconvenção (§2º). Pode ser proposta contra o autor e TERCEIRO (§3º) e pelo réu em LITISCONSÓRCIO com terceiro (§4º). Autor substituto processual: o reconvinte afirma ter direito em face do substituído e propõe contra o autor também como substituto (§5º). O réu pode reconvir INDEPENDENTEMENTE de contestar (§6º)." },
  { id: "cpc-115", lei: "CPC", ref: "CPC arts. 344 e 345 · já caiu: 2011, 2014",
    frente: "Revelia e seus efeitos (arts. 344 e 345): quando a revelia NÃO produz o efeito de presunção de veracidade?",
    verso: "Art. 344: se o réu NÃO CONTESTAR, é considerado REVEL e presumem-se VERDADEIRAS as alegações de fato do autor. Art. 345: NÃO produz o efeito se: I havendo PLURALIDADE de réus, algum deles contestar; II o litígio versar sobre DIREITOS INDISPONÍVEIS; III a inicial não estiver acompanhada de INSTRUMENTO que a lei considere INDISPENSÁVEL à prova do ato; IV as alegações do autor forem INVEROSSÍMEIS ou estiverem em CONTRADIÇÃO com prova dos autos." },
  { id: "cpc-116", lei: "CPC", ref: "CPC art. 346 · já caiu: 2011, 2014",
    frente: "Prazos contra o revel e intervenção no processo (art. 346).",
    verso: "Os prazos contra o revel que NÃO tenha patrono nos autos fluem da data de PUBLICAÇÃO do ato decisório no órgão oficial. O revel pode INTERVIR no processo em QUALQUER FASE, recebendo-o NO ESTADO em que se encontrar." },
  { id: "cpc-117", lei: "CPC", ref: "CPC arts. 347 a 349",
    frente: "Providências preliminares e revel (arts. 347 a 349).",
    verso: "Art. 347: findo o prazo da contestação, o juiz toma as providências preliminares. Art. 348: se o réu não contestar e não ocorrer o efeito da revelia, o juiz manda o autor ESPECIFICAR as provas, se ainda não indicadas. Art. 349: ao RÉU REVEL é lícita a produção de provas contrapostas às alegações do autor, desde que se faça REPRESENTAR nos autos a tempo de praticar os atos indispensáveis à produção." },
  { id: "cpc-118", lei: "CPC", ref: "CPC arts. 350 a 353",
    frente: "Fato impeditivo, modificativo ou extintivo e alegações do réu (arts. 350 a 353).",
    verso: "Art. 350: se o réu alegar fato IMPEDITIVO, MODIFICATIVO ou EXTINTIVO do direito do autor, este é ouvido em 15 DIAS, podendo produzir prova. Art. 351: alegada qualquer matéria do art. 337, o juiz determina a oitiva do autor em 15 DIAS, permitindo prova. Art. 352: verificando irregularidades ou vícios SANÁVEIS, o juiz determina a correção em prazo NUNCA SUPERIOR a 30 DIAS. Art. 353: cumpridas as providências ou não havendo necessidade, o juiz profere julgamento conforme o estado do processo." },
  { id: "cpc-119", lei: "CPC", ref: "CPC art. 354",
    frente: "Extinção do processo no julgamento conforme o estado do processo (art. 354).",
    verso: "Ocorrendo qualquer das hipóteses dos arts. 485 e 487, II e III, o juiz profere SENTENÇA. A decisão pode dizer respeito a apenas PARCELA do processo, caso em que será impugnável por AGRAVO DE INSTRUMENTO." },
  { id: "cpc-120", lei: "CPC", ref: "CPC art. 355",
    frente: "Julgamento antecipado do mérito (art. 355).",
    verso: "O juiz julga antecipadamente o pedido, com sentença de mérito, quando: I NÃO houver necessidade de produção de OUTRAS provas; II o réu for REVEL, ocorrer o efeito do art. 344 e NÃO houver requerimento de prova (art. 349)." },
  { id: "cpc-121", lei: "CPC", ref: "CPC art. 356 · caiu 2024 Q41",
    frente: "Julgamento antecipado PARCIAL do mérito (art. 356): hipóteses, execução e recurso.",
    verso: "O juiz decide parcialmente o mérito quando um ou mais pedidos ou parcela deles: I mostrar-se INCONTROVERSO; II estiver em condições de imediato julgamento (art. 355). Pode reconhecer obrigação LÍQUIDA ou ILÍQUIDA (§1º). A parte pode LIQUIDAR ou EXECUTAR desde logo, INDEPENDENTEMENTE DE CAUÇÃO, ainda que haja recurso (§2º); se houver trânsito em julgado, a execução é DEFINITIVA (§3º). Pode correr em AUTOS SUPLEMENTARES (§4º). A decisão é impugnável por AGRAVO DE INSTRUMENTO (§5º)." },
  { id: "cpc-122", lei: "CPC", ref: "CPC art. 357, I a V",
    frente: "Decisão de saneamento e de organização do processo (art. 357): o que o juiz faz?",
    verso: "I resolve as questões PROCESSUAIS pendentes; II delimita as questões de FATO sobre as quais recairá a prova e especifica os MEIOS de prova; III define a distribuição do ÔNUS DA PROVA (art. 373); IV delimita as questões de DIREITO relevantes; V designa, se necessário, AUDIÊNCIA de instrução e julgamento." },
  { id: "cpc-123", lei: "CPC", ref: "CPC art. 357, §§1º a 9º",
    frente: "Saneamento: esclarecimentos, rol de testemunhas e pauta (art. 357, §§1º a 9º).",
    verso: "§1º: as partes podem pedir ESCLARECIMENTOS ou AJUSTES em prazo comum de 5 DIAS, findo o qual a decisão se torna ESTÁVEL. §2º: delimitação CONSENSUAL das questões, se HOMOLOGADA, vincula partes e juiz. §3º: causa complexa: audiência para saneamento em COOPERAÇÃO. §4º: prova testemunhal: prazo comum NÃO SUPERIOR a 15 DIAS para o rol. §6º: no máximo 10 TESTEMUNHAS, sendo 3, no máximo, para cada fato. §7º: o juiz pode limitar o número. §8º: prova pericial: observa-se o art. 465 e, se possível, fixa-se CALENDÁRIO. §9º: pautas com intervalo mínimo de 1 HORA entre as audiências." },
  { id: "cpc-124", lei: "CPC", ref: "CPC arts. 358 a 360",
    frente: "Abertura, conciliação e poder de polícia na audiência de instrução (arts. 358 a 360).",
    verso: "Art. 358: o juiz declara aberta a audiência e manda APREGOAR as partes e advogados. Art. 359: instalada, o juiz TENTARÁ CONCILIAR as partes, independentemente do emprego anterior de mediação e arbitragem. Art. 360: o juiz exerce o PODER DE POLÍCIA: I manter a ordem e o decoro; II ordenar que se retirem os que se comportarem inconvenientemente; III requisitar força policial; IV tratar com URBANIDADE as partes, advogados, MP, Defensoria e qualquer pessoa; V registrar em ata, com exatidão, todos os requerimentos." },
  { id: "cpc-125", lei: "CPC", ref: "CPC art. 361 · já caiu: 2017",
    frente: "Ordem das provas orais na audiência (art. 361).",
    verso: "Preferencialmente: I o PERITO e os ASSISTENTES TÉCNICOS (respondem aos quesitos de esclarecimentos); II o AUTOR e, em seguida, o RÉU (depoimentos pessoais); III as TESTEMUNHAS do autor e do réu. Enquanto depõem, os advogados e o MP NÃO podem intervir ou apartear sem licença do juiz." },
  { id: "cpc-126", lei: "CPC", ref: "CPC arts. 362 e 363",
    frente: "Adiamento da audiência (arts. 362 e 363).",
    verso: "Art. 362: pode ser adiada: I por CONVENÇÃO das partes; II se não puder comparecer, por motivo justificado, quem deva participar; III por ATRASO injustificado de seu início superior a 30 MINUTOS. O impedimento é comprovado até a ABERTURA da audiência (§1º). O juiz pode DISPENSAR a prova da parte cujo advogado ou defensor não compareceu (§2º). Quem der causa ao adiamento responde pelas despesas acrescidas (§3º). Art. 363: havendo antecipação ou adiamento, o juiz determina a INTIMAÇÃO dos advogados da nova designação." },
  { id: "cpc-127", lei: "CPC", ref: "CPC art. 364 · já caiu: 2017",
    frente: "Debates orais ou razões finais escritas (art. 364).",
    verso: "Finda a instrução, o juiz dá a palavra ao advogado do autor, ao do réu e ao MP, SUCESSIVAMENTE, por 20 MINUTOS cada um, prorrogáveis por 10, a critério do juiz. Litisconsortes: o prazo se divide entre os do mesmo grupo (§1º). Questões complexas: o debate pode ser SUBSTITUÍDO por RAZÕES FINAIS ESCRITAS, em prazos sucessivos de 15 DIAS (§2º)." },
  { id: "cpc-128", lei: "CPC", ref: "CPC arts. 365 a 368 · já caiu: 2010",
    frente: "Audiência una e contínua, sentença, termo e gravação (arts. 365 a 368).",
    verso: "Art. 365: a audiência é UNA e CONTÍNUA, podendo ser excepcionalmente cindida na ausência de perito ou testemunha, com concordância das partes; se impossível concluir no mesmo dia, marca-se continuação para a data MAIS PRÓXIMA, em pauta preferencial. Art. 366: encerrado o debate ou oferecidas as razões finais, o juiz profere sentença em audiência ou em 30 DIAS. Art. 367: o servidor lavra, sob DITADO do juiz, TERMO com o resumo do ocorrido e, por extenso, os despachos, decisões e sentença; subscrevem o juiz, os advogados, o MP e o escrivão (partes dispensadas, salvo ato de disposição sem poderes dos advogados); a audiência pode ser GRAVADA em imagem e áudio (§5º), inclusive diretamente por qualquer das partes, SEM autorização judicial (§6º). Art. 368: a audiência é PÚBLICA, ressalvadas as exceções legais." },
  { id: "cpc-129", lei: "CPC", ref: "CPC arts. 369 a 372",
    frente: "Direito à prova, poderes do juiz e prova emprestada (arts. 369 a 372).",
    verso: "Art. 369: as partes têm direito de empregar todos os meios legais e moralmente legítimos, ainda que não especificados. Art. 370: o juiz, de ofício ou a requerimento, determina as provas necessárias; indefere, em decisão fundamentada, as diligências INÚTEIS ou PROTELATÓRIAS. Art. 371: aprecia a prova independentemente do sujeito que a promoveu e indica as razões de seu convencimento. Art. 372: pode admitir PROVA EMPRESTADA, atribuindo-lhe o valor que considerar adequado, observado o contraditório." },
  { id: "cpc-130", lei: "CPC", ref: "CPC art. 373",
    frente: "Ônus da prova (art. 373).",
    verso: "INCUMBE: I ao AUTOR, quanto ao fato CONSTITUTIVO do seu direito; II ao RÉU, quanto à existência de fato IMPEDITIVO, MODIFICATIVO ou EXTINTIVO. O juiz pode distribuir de modo diverso (teoria dinâmica) nos casos de lei ou diante de impossibilidade ou excessiva dificuldade, ou maior facilidade de obtenção da prova do fato contrário, por DECISÃO FUNDAMENTADA, dando à parte oportunidade de se desincumbir (§1º), sem gerar prova impossível ou excessivamente difícil (§2º). Pode ocorrer por CONVENÇÃO, antes ou durante o processo, SALVO se recair sobre direito INDISPONÍVEL ou tornar excessivamente difícil o exercício do direito (§§3º e 4º)." },
  { id: "cpc-131", lei: "CPC", ref: "CPC arts. 374 a 376",
    frente: "Fatos que não dependem de prova e regras de experiência (arts. 374 a 376).",
    verso: "Art. 374: NÃO dependem de prova os fatos: I NOTÓRIOS; II afirmados por uma parte e CONFESSADOS pela contrária; III admitidos como INCONTROVERSOS; IV em cujo favor milita PRESUNÇÃO legal de existência ou veracidade. Art. 375: o juiz aplica as regras de experiência COMUM e as de experiência TÉCNICA, ressalvado o exame pericial. Art. 376: a parte que alegar direito MUNICIPAL, ESTADUAL, ESTRANGEIRO ou CONSUETUDINÁRIO prova o teor e a vigência, se o juiz determinar." },
  { id: "cpc-132", lei: "CPC", ref: "CPC arts. 377 a 380",
    frente: "Cartas e dever de colaboração com o Judiciário (arts. 377 a 380).",
    verso: "Art. 377: a carta precatória, a rogatória e o auxílio direto SUSPENDEM o julgamento (art. 313, V, b) quando requeridos ANTES do saneamento e a prova for IMPRESCINDÍVEL; as não devolvidas no prazo ou concedidas sem efeito suspensivo podem ser juntadas a QUALQUER momento. Art. 378: NINGUÉM se exime do dever de colaborar com o Judiciário. Art. 379: preservado o direito de não produzir prova contra si, incumbe à PARTE: comparecer e responder, colaborar na inspeção judicial e praticar o ato determinado. Art. 380: incumbe ao TERCEIRO: informar o juiz dos fatos que conheça e EXIBIR coisa ou documento; em caso de descumprimento, MULTA e medidas indutivas, coercitivas, mandamentais ou sub-rogatórias." },
  { id: "cpc-133", lei: "CPC", ref: "CPC art. 381 · já caiu: 2023",
    frente: "Produção antecipada da prova (art. 381): quando é admitida e qual o juízo competente?",
    verso: "Admitida quando: I haja fundado receio de que a verificação de certos fatos se torne IMPOSSÍVEL ou MUITO DIFÍCIL na pendência da ação; II a prova seja suscetível de viabilizar AUTOCOMPOSIÇÃO ou outro meio adequado de solução; III o prévio conhecimento dos fatos possa JUSTIFICAR ou EVITAR o ajuizamento de ação. Competência: juízo do foro onde a prova deva ser produzida OU do foro de domicílio do réu (§2º). NÃO previne a competência para a ação futura (§3º). O juízo ESTADUAL é competente se, na localidade, não houver vara federal, em face da União, autarquia ou empresa pública federal (§4º)." },
  { id: "cpc-134", lei: "CPC", ref: "CPC arts. 382 e 383 · já caiu: 2023",
    frente: "Procedimento da produção antecipada da prova (arts. 382 e 383).",
    verso: "Art. 382: o requerente apresenta as razões da antecipação e menciona com precisão os fatos sobre os quais a prova recairá. O juiz determina a CITAÇÃO dos interessados, salvo se não há caráter contencioso (§1º); NÃO se pronuncia sobre a ocorrência do fato nem sobre as consequências jurídicas (§2º); os interessados podem requerer a produção de qualquer prova relacionada ao mesmo fato (§3º); NÃO se admite DEFESA ou RECURSO, salvo contra decisão que INDEFERIR TOTALMENTE a prova pleiteada pelo requerente originário (§4º). Art. 383: os autos permanecem em cartório por 1 (UM) MÊS para extração de cópias e certidões; depois, são entregues ao promovente." },
  { id: "cpc-135", lei: "CPC", ref: "CPC art. 384",
    frente: "Ata notarial (art. 384).",
    verso: "A existência e o modo de existir de algum fato podem ser ATESTADOS ou DOCUMENTADOS, a requerimento do interessado, mediante ata lavrada por TABELIÃO. Dados representados por IMAGEM ou SOM gravados em arquivos eletrônicos podem constar da ata." },
  { id: "cpc-136", lei: "CPC", ref: "CPC arts. 385 a 387 · já caiu: 2014",
    frente: "Depoimento pessoal (arts. 385 a 387).",
    verso: "Art. 385: cabe à parte requerer o depoimento pessoal da OUTRA parte, sem prejuízo do poder do juiz de ordená-lo de ofício. A parte INTIMADA PESSOALMENTE e advertida da PENA DE CONFESSO que não comparecer ou, comparecendo, se recusar a depor sofre a pena (§1º). É vedado a quem ainda não depôs ASSISTIR ao interrogatório da outra parte (§2º). Parte em outra comarca: videoconferência (§3º). Art. 386: se a parte deixar de responder ou empregar evasivas, o juiz declara na sentença se houve RECUSA de depor. Art. 387: a parte responde PESSOALMENTE, sem escritos preparados, podendo consultar NOTAS BREVES para completar esclarecimentos." },
  { id: "cpc-137", lei: "CPC", ref: "CPC art. 388",
    frente: "Fatos sobre os quais a parte NÃO é obrigada a depor (art. 388).",
    verso: "I fatos CRIMINOSOS ou TORPES que lhe forem imputados; II fatos a cujo respeito, por ESTADO ou PROFISSÃO, deva guardar SIGILO; III fatos sobre os quais não possa responder sem DESONRA própria, de seu cônjuge, companheiro ou parente em grau sucessível; IV fatos que coloquem em PERIGO a VIDA do depoente ou dessas pessoas. NÃO se aplica às AÇÕES DE ESTADO e de FAMÍLIA." },
  { id: "cpc-138", lei: "CPC", ref: "CPC arts. 389 a 392",
    frente: "Confissão (arts. 389 a 392).",
    verso: "Art. 389: há CONFISSÃO, judicial ou extrajudicial, quando a parte admite a verdade de fato CONTRÁRIO ao seu interesse e FAVORÁVEL ao adversário. Art. 390: a judicial pode ser ESPONTÂNEA (pela parte ou por representante com PODER ESPECIAL) ou PROVOCADA (consta do termo de depoimento pessoal). Art. 391: faz prova CONTRA o confitente, sem prejudicar os LITISCONSORTES; em ações sobre bens imóveis ou direitos reais sobre imóveis alheios, a confissão de um cônjuge ou companheiro NÃO VALE sem a do outro, salvo separação absoluta de bens. Art. 392: NÃO vale a admissão de fatos relativos a DIREITOS INDISPONÍVEIS; é ineficaz se feita por quem não pode dispor; a do representante só é eficaz nos limites em que este vincula o representado." },
  { id: "cpc-139", lei: "CPC", ref: "CPC arts. 393 a 395",
    frente: "Irrevogabilidade, confissão extrajudicial e indivisibilidade (arts. 393 a 395).",
    verso: "Art. 393: a confissão é IRREVOGÁVEL, mas pode ser ANULADA se decorreu de ERRO DE FATO ou COAÇÃO; a legitimidade é EXCLUSIVA do confitente e se transfere aos herdeiros se ele falecer após a propositura. Art. 394: a confissão EXTRAJUDICIAL ORAL só tem eficácia nos casos em que a lei não exija prova LITERAL. Art. 395: a confissão é, em regra, INDIVISÍVEL; cinde-se quando o confitente aduz FATOS NOVOS capazes de constituir fundamento de defesa de direito material ou de reconvenção." },
  { id: "cpc-140", lei: "CPC", ref: "CPC arts. 396 a 398",
    frente: "Exibição de documento ou coisa: pedido e resposta (arts. 396 a 398).",
    verso: "Art. 396: o juiz pode ordenar que a PARTE exiba documento ou coisa em seu poder. Art. 397: o pedido contém: I a DESCRIÇÃO do documento ou coisa (ou de categorias); II a FINALIDADE da prova, com os fatos relacionados; III as CIRCUNSTÂNCIAS em que se funda para afirmar que existe e está em poder da parte contrária. Art. 398: o requerido responde em 5 DIAS da intimação; se afirmar que não possui, o juiz permite ao requerente provar por qualquer meio que a declaração é falsa." },
  { id: "cpc-141", lei: "CPC", ref: "CPC arts. 399 e 400",
    frente: "Recusa à exibição e consequências (arts. 399 e 400).",
    verso: "Art. 399: o juiz NÃO admite a recusa se: I o requerido tiver OBRIGAÇÃO LEGAL de exibir; II tiver ALUDIDO ao documento ou coisa, no processo, com o intuito de constituir prova; III o documento, por seu conteúdo, for COMUM às partes. Art. 400: o juiz admite como VERDADEIROS os fatos que a parte pretendia provar se: I o requerido não efetuar a exibição nem fizer declaração no prazo; II a recusa for havida por ilegítima. Pode adotar medidas indutivas, coercitivas, mandamentais ou sub-rogatórias." },
  { id: "cpc-142", lei: "CPC", ref: "CPC arts. 401 a 403",
    frente: "Exibição de documento ou coisa em poder de TERCEIRO (arts. 401 a 403).",
    verso: "Art. 401: o juiz ordena a CITAÇÃO do terceiro para responder em 15 DIAS. Art. 402: se o terceiro negar a obrigação de exibir ou a posse, o juiz designa AUDIÊNCIA ESPECIAL, tomando o depoimento dele, das partes e, se necessário, de testemunhas, e depois decide. Art. 403: se o terceiro, sem justo motivo, se recusar, o juiz manda DEPOSITAR em cartório ou outro lugar, em 5 DIAS, com ressarcimento das despesas pelo requerente; descumprida a ordem, expede MANDADO DE APREENSÃO, requisitando força policial se necessário, sem prejuízo de DESOBEDIÊNCIA, MULTA e outras medidas." },
  { id: "cpc-143", lei: "CPC", ref: "CPC art. 404",
    frente: "Quando a parte e o terceiro se ESCUSAM de exibir documento ou coisa (art. 404)?",
    verso: "I concernente a NEGÓCIOS da própria VIDA DA FAMÍLIA; II sua apresentação puder violar DEVER DE HONRA; III sua publicidade redundar em DESONRA à parte ou ao terceiro e aos parentes até o 3º grau, ou lhes representar PERIGO DE AÇÃO PENAL; IV a exibição acarretar divulgação de fatos a cujo respeito, por estado ou profissão, devam guardar SEGREDO; V outros motivos graves, a juízo do juiz; VI disposição LEGAL que justifique a recusa. Se disser respeito a só parte do documento, exibe-se a outra em cartório, para extração de cópia, lavrando-se AUTO circunstanciado." },
  { id: "cpc-144", lei: "CPC", ref: "CPC arts. 405 a 407",
    frente: "Força probante do documento público (arts. 405 a 407).",
    verso: "Art. 405: o documento PÚBLICO faz prova não só da sua FORMAÇÃO, mas também dos FATOS que o escrivão, chefe de secretaria, tabelião ou servidor declarar que ocorreram em sua PRESENÇA. Art. 406: quando a lei exigir INSTRUMENTO PÚBLICO como da SUBSTÂNCIA do ato, nenhuma outra prova, por mais especial que seja, pode suprir-lhe a falta. Art. 407: o documento feito por oficial público INCOMPETENTE ou sem as FORMALIDADES legais, SUBSCRITO PELAS PARTES, tem a mesma eficácia probatória do documento PARTICULAR." },
  { id: "cpc-145", lei: "CPC", ref: "CPC arts. 408 a 410",
    frente: "Documento particular: presunção, data e autoria (arts. 408 a 410).",
    verso: "Art. 408: as declarações do documento particular escrito e assinado (ou só assinado) presumem-se VERDADEIRAS em relação ao SIGNATÁRIO; se contiver declaração de CIÊNCIA de fato, prova a ciência, não o fato em si, cabendo o ônus de provar a quem tem interesse na veracidade. Art. 409: a DATA, havendo dúvida ou impugnação entre os litigantes, prova-se por todos os meios; EM RELAÇÃO A TERCEIROS considera-se datado: no dia do REGISTRO; desde a MORTE de algum signatário; a partir da IMPOSSIBILIDADE FÍSICA de signatário; da APRESENTAÇÃO em repartição pública ou em juízo; do ato ou fato que estabeleça com certeza a anterioridade. Art. 410: autor do documento particular é quem o fez e o assinou; aquele por conta de quem foi feito, estando assinado; aquele que, mandando compô-lo, não o firmou porque, pela experiência comum, não se costuma assinar (livros empresariais e assentos domésticos)." },
  { id: "cpc-146", lei: "CPC", ref: "CPC arts. 411 a 414",
    frente: "Autenticidade do documento, indivisibilidade e telegrama (arts. 411 a 414).",
    verso: "Art. 411: é AUTÊNTICO quando: I o TABELIÃO reconhecer a firma do signatário; II a autoria estiver identificada por outro meio legal de certificação, inclusive ELETRÔNICO; III NÃO houver IMPUGNAÇÃO da parte contra quem foi produzido. Art. 412: o documento particular de cuja autenticidade não se duvida prova que o autor fez a declaração; é INDIVISÍVEL, vedado aceitar os fatos favoráveis e recusar os contrários, salvo se provar que não ocorreram. Art. 413: telegrama, radiograma ou outro meio de transmissão tem a força do documento particular se o original da estação expedidora tiver sido ASSINADO pelo remetente (firma reconhecível por tabelião). Art. 414: presume-se conforme com o original, provando as datas de expedição e de recebimento." },
  { id: "cpc-147", lei: "CPC", ref: "CPC arts. 415 a 421",
    frente: "Cartas, notas do credor e livros empresariais (arts. 415 a 421).",
    verso: "Art. 415: cartas e registros domésticos provam CONTRA quem os escreveu quando: enunciam o recebimento de CRÉDITO; contêm anotação para suprir a falta de título em favor do credor; expressam conhecimento de fatos para os quais não se exija determinada prova. Art. 416: a NOTA escrita pelo CREDOR em documento representativo da obrigação, ainda que não assinada, faz prova em benefício do DEVEDOR. Art. 417: livros empresariais provam CONTRA seu autor (que pode demonstrar que os lançamentos não correspondem à verdade). Art. 418: provam A FAVOR de seu autor no litígio entre EMPRESÁRIOS, se preenchidos os requisitos legais. Art. 419: a escrituração é INDIVISÍVEL. Art. 420: exibição INTEGRAL, a requerimento: liquidação de sociedade, sucessão por morte de sócio e quando a lei determinar. Art. 421: exibição PARCIAL, de OFÍCIO." },
  { id: "cpc-148", lei: "CPC", ref: "CPC arts. 422 a 425",
    frente: "Reproduções, cópias e documentos com a mesma força dos originais (arts. 422 a 425).",
    verso: "Art. 422: qualquer reprodução mecânica (fotográfica, cinematográfica, fonográfica) faz prova se a conformidade com o original não for impugnada; fotografias digitais e da internet: se impugnadas, apresenta-se a autenticação eletrônica ou realiza-se PERÍCIA; fotografia de jornal ou revista: exige-se um EXEMPLAR ORIGINAL do periódico se impugnada; aplica-se à forma impressa de mensagem eletrônica. Art. 423: reproduções de documentos particulares valem como CERTIDÕES se o escrivão certificar a conformidade. Art. 424: a CÓPIA de documento particular tem o mesmo valor do original, cabendo ao escrivão, intimadas as partes, conferir e certificar. Art. 425: fazem a mesma prova que os originais: certidões textuais extraídas pelo escrivão; traslados e certidões de oficial público; reproduções de documentos públicos autenticadas ou conferidas em cartório; cópias de peças do PRÓPRIO processo declaradas autênticas pelo ADVOGADO, sob sua responsabilidade pessoal; extratos digitais de bancos de dados atestados pelo emitente; reproduções DIGITALIZADAS juntadas por órgãos da justiça, MP, Defensoria, procuradorias, repartições e advogados, ressalvada alegação de adulteração. Os originais digitalizados são preservados até o fim do prazo da AÇÃO RESCISÓRIA (§1º)." },
  { id: "cpc-149", lei: "CPC", ref: "CPC arts. 426 a 429",
    frente: "Fé do documento, falsidade e ônus da prova (arts. 426 a 429).",
    verso: "Art. 426: o juiz aprecia fundamentadamente a fé do documento que, em ponto substancial, contiver ENTRELINHA, EMENDA, BORRÃO ou CANCELAMENTO. Art. 427: cessa a fé do documento público ou particular declarado judicialmente FALSO; FALSIDADE é formar documento não verdadeiro ou alterar documento verdadeiro. Art. 428: cessa a fé do particular quando impugnada sua autenticidade, enquanto não provada a veracidade, ou quando, ASSINADO EM BRANCO, impugnado o conteúdo por PREENCHIMENTO ABUSIVO. Art. 429: o ônus incumbe: na FALSIDADE ou preenchimento abusivo, à parte que a ARGUIR; na impugnação da AUTENTICIDADE, à parte que PRODUZIU o documento." },
  { id: "cpc-150", lei: "CPC", ref: "CPC arts. 430 a 433",
    frente: "Arguição de falsidade (arts. 430 a 433).",
    verso: "Art. 430: deve ser suscitada na CONTESTAÇÃO, na RÉPLICA ou no prazo de 15 DIAS, contado da intimação da juntada do documento; resolve-se como QUESTÃO INCIDENTAL, salvo se a parte requerer que o juiz a decida como QUESTÃO PRINCIPAL (art. 19, II). Art. 431: a parte expõe os motivos e os meios de prova. Art. 432: ouvida a outra parte em 15 DIAS, realiza-se EXAME PERICIAL, que não se faz se a parte que produziu o documento concordar em retirá-lo. Art. 433: suscitada como questão principal, a declaração consta do DISPOSITIVO da sentença e faz COISA JULGADA." },
  { id: "cpc-151", lei: "CPC", ref: "CPC arts. 434 a 438",
    frente: "Produção da prova documental (arts. 434 a 438).",
    verso: "Art. 434: incumbe à parte instruir a INICIAL ou a CONTESTAÇÃO com os documentos destinados a provar suas alegações; reprodução cinematográfica ou fonográfica é exposta em AUDIÊNCIA. Art. 435: é lícito juntar documentos NOVOS em qualquer tempo, quando destinados a provar fatos ocorridos depois dos articulados ou contrapor os produzidos; também documentos formados após a inicial ou a contestação ou que se tornaram conhecidos ou acessíveis depois, cabendo à parte comprovar o motivo. Art. 436: a parte intimada a falar sobre documento pode: impugnar a ADMISSIBILIDADE; impugnar a AUTENTICIDADE; suscitar a FALSIDADE; manifestar-se sobre o CONTEÚDO; a impugnação exige argumentação ESPECÍFICA, sem alegação genérica de falsidade. Art. 437: o RÉU manifesta-se na contestação sobre documentos da inicial; o AUTOR, na RÉPLICA sobre os da contestação; juntado documento a pedido, a outra parte tem 15 DIAS (o juiz pode dilatar). Art. 438: o juiz requisita às repartições públicas certidões e procedimentos administrativos (causas de União, Estados, DF, Municípios e administração indireta); recebidos os autos, extrai-se em 1 MÊS, máximo e improrrogável, certidões e reproduções." },
  { id: "cpc-152", lei: "CPC", ref: "CPC arts. 439 a 441",
    frente: "Documentos eletrônicos (arts. 439 a 441).",
    verso: "Art. 439: no processo CONVENCIONAL, depende de CONVERSÃO à forma impressa e da verificação de AUTENTICIDADE. Art. 440: o juiz aprecia o valor probante do documento eletrônico NÃO convertido, assegurado às partes o acesso ao teor. Art. 441: são admitidos os documentos eletrônicos produzidos e conservados com observância da LEGISLAÇÃO específica." },
  { id: "cpc-153", lei: "CPC", ref: "CPC arts. 442 a 446 · já caiu: 2010",
    frente: "Prova testemunhal: admissibilidade (arts. 442 a 446).",
    verso: "Art. 442: é SEMPRE admissível, salvo disposição em contrário. Art. 443: o juiz INDEFERE a inquirição sobre fatos: I já provados por DOCUMENTO ou CONFISSÃO; II que só por DOCUMENTO ou EXAME PERICIAL puderem ser provados. Art. 444: quando a lei exigir prova escrita, admite-se a testemunhal com COMEÇO DE PROVA POR ESCRITO emanado da parte contra quem se produz. Art. 445: também se o credor não pôde, moral ou materialmente, obter prova escrita (parentesco, depósito necessário, hospedagem em hotel, práticas comerciais). Art. 446: é lícito provar com testemunhas, nos contratos SIMULADOS, a divergência entre a vontade real e a declarada, e, nos contratos em geral, os VÍCIOS DE CONSENTIMENTO." },
  { id: "cpc-154", lei: "CPC", ref: "CPC art. 447 · já caiu: 2010",
    frente: "Quem NÃO pode depor como testemunha: incapazes, impedidos e suspeitos (art. 447).",
    verso: "Podem depor todas as pessoas, EXCETO as incapazes, impedidas ou suspeitas. INCAPAZES: o interdito por enfermidade ou deficiência mental; quem, ao tempo dos fatos, não podia discerni-los ou, ao depor, não está habilitado a transmitir as percepções; MENOR DE 16 ANOS; o CEGO e o SURDO quando a ciência do fato depender dos sentidos que lhes faltam. IMPEDIDOS: o cônjuge, companheiro, ascendente e descendente em qualquer grau e colateral até o 3º GRAU de alguma das partes (salvo interesse público ou causa de estado sem outra prova); o que é PARTE; o que intervém em nome de uma parte (tutor, representante legal da pessoa jurídica, juiz, advogado e outros que assistam ou tenham assistido). SUSPEITOS: o INIMIGO da parte ou seu AMIGO ÍNTIMO; o que tiver INTERESSE no litígio. Menores, impedidos ou suspeitos podem ser admitidos, SEM compromisso, valor a critério do juiz." },
  { id: "cpc-155", lei: "CPC", ref: "CPC arts. 448 e 449 · já caiu: 2010",
    frente: "Fatos sobre os quais a testemunha NÃO é obrigada a depor e lugar da oitiva (arts. 448 e 449).",
    verso: "Art. 448: I fatos que lhe acarretem GRAVE DANO, bem como ao seu cônjuge, companheiro e parentes até o 3º grau; II fatos a cujo respeito, por ESTADO ou PROFISSÃO, deva guardar SIGILO. Art. 449: salvo disposição especial, são ouvidas na SEDE DO JUÍZO; se impossibilitada de comparecer, mas não de depor, o juiz designa dia, hora e lugar para inquiri-la." },
  { id: "cpc-156", lei: "CPC", ref: "CPC arts. 450 a 452",
    frente: "Rol de testemunhas, substituição e juiz arrolado (arts. 450 a 452).",
    verso: "Art. 450: o rol contém, sempre que possível, nome, profissão, estado civil, idade, CPF, RG e endereço completo da residência e do trabalho. Art. 451: apresentado o rol, só se substitui a testemunha que: I FALECER; II por ENFERMIDADE não puder depor; III mudar de residência ou local de trabalho e NÃO for encontrada. Art. 452: o juiz da causa arrolado como testemunha: I declara-se IMPEDIDO se souber de fatos que possam influir na decisão (vedado à parte desistir); II se nada souber, manda EXCLUIR seu nome." },
  { id: "cpc-157", lei: "CPC", ref: "CPC arts. 453 e 454 · já caiu: 2010",
    frente: "Onde depõem as testemunhas e quem é inquirido em sua residência ou local de função (arts. 453 e 454).",
    verso: "Art. 453: depõem na audiência perante o juiz da causa, exceto as que prestam depoimento ANTECIPADAMENTE e as inquiridas por CARTA; testemunha em outra comarca pode ser ouvida por VIDEOCONFERÊNCIA. Art. 454: são inquiridos em sua residência ou onde exercem a função: Presidente e Vice-Presidente da República; ministros de Estado; ministros do STF, conselheiros do CNJ e ministros do STJ, STM, TSE, TST e TCU; Procurador-Geral da República e conselheiros do CNMP; AGU, procuradores-gerais do Estado e do Município, defensores públicos-gerais; senadores e deputados federais; governadores; prefeito; deputados estaduais e distritais; desembargadores e conselheiros dos Tribunais de Contas; procurador-geral de justiça; embaixador de país que conceda idêntica prerrogativa. O juiz pede que indique dia, hora e local; passado 1 MÊS sem manifestação, designa dia, hora e local." },
  { id: "cpc-158", lei: "CPC", ref: "CPC art. 455",
    frente: "Intimação da testemunha pelo advogado (art. 455).",
    verso: "Cabe ao ADVOGADO da parte informar ou intimar a testemunha por ele arrolada do dia, hora e local, dispensando-se a intimação do juízo. A intimação é por CARTA com AVISO DE RECEBIMENTO, juntando-se aos autos cópia e comprovante com antecedência de pelo menos 3 DIAS (§1º). A parte pode comprometer-se a levá-la, presumindo-se DESISTÊNCIA se não comparecer (§2º). A INÉRCIA na intimação importa desistência (§3º). A intimação é PELA VIA JUDICIAL quando: frustrada a do §1º; demonstrada a necessidade; o rol tiver SERVIDOR PÚBLICO ou MILITAR (requisitado ao chefe); a testemunha foi arrolada pelo MP ou DEFENSORIA; for das autoridades do art. 454 (§4º). Intimada e ausente sem justificativa, será CONDUZIDA e responderá pelas despesas do adiamento (§5º)." },
  { id: "cpc-159", lei: "CPC", ref: "CPC arts. 456 a 458",
    frente: "Inquirição das testemunhas, contradita e compromisso (arts. 456 a 458).",
    verso: "Art. 456: o juiz inquire SEPARADA e SUCESSIVAMENTE, primeiro as do AUTOR, depois as do RÉU, e providencia para que uma não ouça a outra; pode alterar a ordem se as partes concordarem. Art. 457: antes de depor, a testemunha é QUALIFICADA e informa parentesco ou interesse; a parte pode CONTRADITAR (incapacidade, impedimento, suspeição), provando com documentos ou até 3 TESTEMUNHAS, inquiridas em separado (§1º); provados os fatos, o juiz DISPENSA a testemunha ou a ouve como INFORMANTE (§2º); a testemunha pode pedir ESCUSA (§3º). Art. 458: a testemunha presta COMPROMISSO de dizer a verdade; o juiz a adverte de que incorre em sanção PENAL quem faz afirmação falsa, cala ou oculta a verdade." },
  { id: "cpc-160", lei: "CPC", ref: "CPC arts. 459 e 460",
    frente: "Perguntas às testemunhas e documentação do depoimento (arts. 459 e 460).",
    verso: "Art. 459: as perguntas são formuladas pelas partes DIRETAMENTE, começando pela que arrolou; o juiz não admite as que possam INDUZIR a resposta, não tenham relação com as questões de fato ou repitam outra já respondida; pode inquirir antes ou depois (§1º); tratar com URBANIDADE, sem perguntas impertinentes, capciosas ou vexatórias (§2º); as indeferidas são transcritas se a parte requerer (§3º). Art. 460: o depoimento pode ser documentado por GRAVAÇÃO; digitado ou registrado por taquigrafia ou estenotipia, é assinado pelo juiz, pelo depoente e pelos procuradores (§1º)." },
  { id: "cpc-161", lei: "CPC", ref: "CPC arts. 461 a 463",
    frente: "Acareação e testemunha: o que o juiz pode ordenar (arts. 461 a 463)?",
    verso: "Art. 461: de ofício ou a requerimento, I inquirição de testemunhas referidas nas declarações da parte ou das testemunhas; II ACAREAÇÃO de 2 ou mais testemunhas, ou de testemunha com a parte, quando divergirem sobre fato determinado que possa influir na decisão (os acareados são reperguntados; pode ser por videoconferência). Art. 462: a testemunha pode requerer o pagamento da despesa do comparecimento; a parte paga ou deposita em cartório em 3 DIAS. Art. 463: o depoimento em juízo é SERVIÇO PÚBLICO; empregado celetista não perde salário nem tempo de serviço." },
  { id: "cpc-162", lei: "CPC", ref: "CPC art. 464",
    frente: "Prova pericial: em que consiste e quando o juiz INDEFERE a perícia (art. 464)?",
    verso: "Consiste em EXAME, VISTORIA ou AVALIAÇÃO. Indefere quando: I a prova do fato não depender de conhecimento especial de técnico; II for desnecessária em vista de outras provas; III a verificação for impraticável. Em substituição, pode determinar PROVA TÉCNICA SIMPLIFICADA (inquirição de especialista pelo juiz, com formação acadêmica específica) quando o ponto for de menor complexidade." },
  { id: "cpc-163", lei: "CPC", ref: "CPC art. 465 · já caiu: 2021",
    frente: "Perito: prazos das partes e do perito após a nomeação (art. 465).",
    verso: "Partes, em 15 DIAS da intimação da nomeação: arguir impedimento/suspeição, indicar ASSISTENTE TÉCNICO, apresentar QUESITOS. Perito, em 5 DIAS: proposta de HONORÁRIOS, currículo com comprovação de especialização e contatos profissionais. Partes se manifestam sobre a proposta em prazo comum de 5 DIAS; depois o juiz arbitra. Pode autorizar pagamento de até 50% dos honorários no INÍCIO; o restante só ao FINAL, após laudo e esclarecimentos. Perícia inconclusiva ou deficiente: o juiz pode REDUZIR a remuneração." },
  { id: "cpc-164", lei: "CPC", ref: "CPC arts. 466 a 468 · já caiu: 2021",
    frente: "Perito e assistentes técnicos: compromisso, impedimento e substituição (arts. 466 a 468).",
    verso: "Art. 466: o perito cumpre o encargo independentemente de TERMO de compromisso; os ASSISTENTES TÉCNICOS são de confiança da parte e NÃO se sujeitam a impedimento ou suspeição; o perito deve dar-lhes acesso às diligências com comunicação prévia de pelo menos 5 DIAS. Art. 467: o perito pode escusar-se ou ser recusado por impedimento ou suspeição (novo perito). Art. 468: substitui-se o perito que faltar-lhe conhecimento técnico ou, sem motivo legítimo, não cumprir o encargo no prazo; comunica-se à corporação profissional e pode haver multa; o substituído restitui os valores em 15 DIAS, sob pena de ficar impedido de atuar como perito por 5 ANOS." },
  { id: "cpc-165", lei: "CPC", ref: "CPC arts. 469 a 472",
    frente: "Quesitos suplementares, perícia consensual e dispensa da perícia (arts. 469 a 472).",
    verso: "Art. 469: quesitos SUPLEMENTARES durante a diligência (respondidos previamente ou na audiência); escrivão dá ciência à parte contrária. Art. 470: o juiz INDEFERE quesitos impertinentes e FORMULA os que entender necessários. Art. 471: partes plenamente capazes, em causa que admita AUTOCOMPOSIÇÃO, podem de comum acordo escolher o perito (indicando já os assistentes); a perícia consensual SUBSTITUI a do perito nomeado. Art. 472: o juiz pode DISPENSAR a perícia se as partes, na inicial e na contestação, apresentarem pareceres técnicos ou documentos elucidativos suficientes." },
  { id: "cpc-166", lei: "CPC", ref: "CPC arts. 473 a 477",
    frente: "Laudo pericial: conteúdo e prazos (arts. 473 a 477).",
    verso: "Art. 473: contém exposição do OBJETO, análise técnica ou científica, indicação do MÉTODO (predominantemente aceito) e RESPOSTA CONCLUSIVA a todos os quesitos (do juiz, partes e MP); linguagem simples; é VEDADO ultrapassar os limites da designação ou emitir opiniões pessoais. Art. 475: perícia complexa de mais de uma área → mais de um perito. Art. 476: prorrogação, UMA vez, pela METADE do prazo original. Art. 477: laudo protocolado pelo menos 20 DIAS antes da audiência; partes manifestam-se em 15 DIAS (comum), assistentes técnicos em igual prazo; perito esclarece em 15 DIAS; se persistir dúvida, intimado a comparecer à audiência, por meio eletrônico, com pelo menos 10 DIAS de antecedência." },
  { id: "cpc-167", lei: "CPC", ref: "CPC arts. 478 a 480",
    frente: "Perícia em documento/médico-legal, valoração do laudo e nova perícia (arts. 478 a 480).",
    verso: "Art. 478: autenticidade ou falsidade de documento, ou natureza MÉDICO-LEGAL → perito escolhido de preferência entre técnicos de estabelecimentos OFICIAIS. Art. 479: o juiz aprecia a perícia conforme o art. 371 e indica na sentença os motivos de considerar ou não as conclusões (não fica adstrito ao laudo). Art. 480: nova perícia, de ofício ou a requerimento, quando a matéria não estiver suficientemente esclarecida; tem por objeto os MESMOS fatos, corrige omissão ou inexatidão e NÃO SUBSTITUI a primeira (o juiz aprecia o valor de ambas)." },
  { id: "cpc-168", lei: "CPC", ref: "CPC arts. 481 a 484",
    frente: "Inspeção judicial (arts. 481 a 484).",
    verso: "Art. 481: o juiz, de ofício ou a requerimento, em QUALQUER FASE do processo, pode inspecionar pessoas ou coisas. Art. 482: pode ser assistido por perito(s). Art. 483: vai ao local quando julgar necessário, a coisa não puder ser apresentada sem consideráveis despesas ou graves dificuldades, ou para determinar a RECONSTITUIÇÃO dos fatos; as partes têm SEMPRE direito de assistir. Art. 484: lavra-se AUTO CIRCUNSTANCIADO (pode ter desenho, gráfico ou fotografia)." },
  { id: "cpc-169", lei: "CPC", ref: "CPC art. 485, I a V · já caiu",
    frente: "Quando o juiz NÃO resolve o mérito (art. 485, I a V)?",
    verso: "I indeferir a PETIÇÃO INICIAL; II processo parado mais de 1 ANO por negligência das partes; III autor abandonar a causa por mais de 30 DIAS; IV ausência de pressupostos de constituição e desenvolvimento válido e regular; V perempção, litispendência ou coisa julgada." },
  { id: "cpc-170", lei: "CPC", ref: "CPC art. 485, VI a X e §§ · já caiu",
    frente: "Art. 485, VI a X e §§: demais hipóteses, intimação pessoal, desistência e retratação.",
    verso: "VI ausência de LEGITIMIDADE ou INTERESSE processual; VII convenção de ARBITRAGEM; VIII HOMOLOGAR a desistência da ação; IX morte da parte em ação intransmissível; X demais casos do Código. §1º: nos incisos II e III a parte é intimada PESSOALMENTE para suprir a falta em 5 DIAS. §3º: de ofício, em qualquer tempo e grau, enquanto não houver trânsito em julgado: IV, V, VI e IX. §4º: contestada a ação, desistência só COM CONSENTIMENTO do réu; §5º: desistência até a SENTENÇA. §6º: abandono após contestação exige requerimento do réu. §7º: apelação → o juiz tem 5 DIAS para retratar-se." },
  { id: "cpc-171", lei: "CPC", ref: "CPC art. 486",
    frente: "Sentença sem resolução de mérito: pode propor de novo a ação? (art. 486)",
    verso: "SIM, em regra. Mas a nova ação depende da CORREÇÃO DO VÍCIO nos casos de litispendência e dos incisos I, IV, VI e VII do art. 485; a inicial só é despachada com prova do pagamento das custas e honorários; se o autor der causa 3 VEZES a sentença por ABANDONO, não pode propor nova ação com o mesmo objeto (resguardada a defesa)." },
  { id: "cpc-172", lei: "CPC", ref: "CPC arts. 487 e 488",
    frente: "Quando há RESOLUÇÃO DE MÉRITO (arts. 487 e 488)?",
    verso: "I acolher ou rejeitar o PEDIDO (ação ou reconvenção); II decidir sobre DECADÊNCIA ou PRESCRIÇÃO; III HOMOLOGAR: a) reconhecimento da procedência do pedido; b) TRANSAÇÃO; c) RENÚNCIA à pretensão. Prescrição e decadência não são reconhecidas sem antes ouvir as partes (salvo improcedência liminar, art. 332, §1º). Art. 488: sendo possível, resolve-se o mérito se a decisão for favorável à parte a quem aproveitaria a extinção sem mérito." },
  { id: "cpc-173", lei: "CPC", ref: "CPC art. 489 · já caiu",
    frente: "Elementos essenciais da sentença (art. 489).",
    verso: "I RELATÓRIO (nomes das partes, identificação do caso, suma do pedido e da contestação, principais ocorrências); II FUNDAMENTOS (questões de fato e de direito); III DISPOSITIVO (resolve as questões principais). Não se considera fundamentada a decisão que: só indica ou parafraseia ato normativo; usa conceito indeterminado sem explicar; invoca motivos que serviriam a qualquer decisão; não enfrenta TODOS os argumentos capazes de infirmar a conclusão; invoca precedente/súmula sem identificar fundamentos; deixa de seguir súmula/precedente invocado sem distinguir ou demonstrar superação." },
  { id: "cpc-174", lei: "CPC", ref: "CPC arts. 490 a 493 · já caiu: 2013",
    frente: "Limites da sentença: pedido certo e fato superveniente (arts. 491 a 493).",
    verso: "Art. 491: na obrigação de pagar quantia, mesmo com pedido genérico, a decisão define desde logo a extensão, correção, juros etc., SALVO se não for possível determinar o montante ou a apuração depender de prova demorada ou dispendiosa (→ LIQUIDAÇÃO). Art. 492: é VEDADO decisão de natureza DIVERSA da pedida, condenação em quantidade SUPERIOR ou objeto DIVERSO (julgamento ultra/extra petita); a decisão deve ser CERTA, ainda que resolva relação condicional. Art. 493: fato constitutivo, modificativo ou extintivo SUPERVENIENTE é considerado de ofício ou a requerimento; se de ofício, ouvem-se as partes." },
  { id: "cpc-175", lei: "CPC", ref: "CPC art. 494 · já caiu: 2007, 2013",
    frente: "Publicada a sentença, em que casos o juiz pode alterá-la (art. 494)?",
    verso: "Só: I para corrigir, de ofício ou a requerimento, INEXATIDÕES MATERIAIS ou ERROS DE CÁLCULO; II por meio de EMBARGOS DE DECLARAÇÃO." },
  { id: "cpc-176", lei: "CPC", ref: "CPC art. 495",
    frente: "Hipoteca judiciária (art. 495).",
    verso: "A decisão que condena ao pagamento em dinheiro (e a que converte obrigação em prestação pecuniária) vale como título de hipoteca judiciária — mesmo com condenação GENÉRICA, mesmo cabendo cumprimento provisório e mesmo com recurso de efeito suspensivo. Realiza-se por cópia da sentença no registro de imóveis, SEM ordem judicial; a parte informa o juízo em até 15 DIAS; gera direito de PREFERÊNCIA. Reformada a decisão, responde SEM CULPA pelos danos." },
  { id: "cpc-177", lei: "CPC", ref: "CPC art. 496 · já caiu",
    frente: "Remessa necessária: casos e valores de dispensa (art. 496).",
    verso: "Sujeita ao duplo grau, só produzindo efeito depois de confirmada pelo tribunal, a sentença: I proferida CONTRA União, Estados, DF, Municípios e suas autarquias e fundações de direito público; II que julgar PROCEDENTES, no todo ou em parte, os embargos à execução fiscal. Não interposta apelação, o juiz remete; se não o fizer, o presidente do tribunal AVOCA os autos. NÃO se aplica se o valor certo e líquido for inferior a: 1.000 salários-mínimos (União e suas autarquias/fundações); 500 (Estados, DF, capitais e suas autarquias/fundações); 100 (demais Municípios)." },
  { id: "cpc-178", lei: "CPC", ref: "CPC art. 496, § 4º",
    frente: "Remessa necessária: quando NÃO se aplica pelo fundamento da sentença (art. 496, §4º)?",
    verso: "Quando a sentença se funda em: I SÚMULA de tribunal superior; II acórdão do STF ou STJ em RECURSOS REPETITIVOS; III entendimento firmado em IRDR ou incidente de assunção de competência; IV entendimento coincidente com orientação vinculante administrativa do próprio ente público (manifestação, parecer ou súmula administrativa)." },
  { id: "cpc-179", lei: "CPC", ref: "CPC arts. 497 a 501 · já caiu: 2023",
    frente: "Obrigações de fazer, não fazer, entregar coisa e declaração de vontade (arts. 497 a 501).",
    verso: "Art. 497: procedente o pedido, o juiz concede TUTELA ESPECÍFICA ou providências que assegurem o RESULTADO PRÁTICO EQUIVALENTE; para inibir ilícito (prática, reiteração, continuação ou remoção) é IRRELEVANTE a demonstração de DANO, CULPA ou DOLO. Art. 498: entrega de coisa → o juiz fixa PRAZO. Art. 499: só converte em PERDAS E DANOS se o autor requerer ou se impossível a tutela específica ou o resultado equivalente. Art. 500: perdas e danos sem prejuízo da MULTA periódica. Art. 501: declaração de vontade → a sentença transitada em julgado produz todos os efeitos da declaração não emitida." },
  { id: "cpc-180", lei: "CPC", ref: "CPC arts. 502 a 504",
    frente: "Coisa julgada material: conceito, limites e o que NÃO faz coisa julgada (arts. 502 a 504).",
    verso: "Art. 502: é a autoridade que torna IMUTÁVEL e INDISCUTÍVEL a decisão de MÉRITO não mais sujeita a recurso. Art. 503: tem força de lei nos limites da QUESTÃO PRINCIPAL expressamente decidida; aplica-se à QUESTÃO PREJUDICIAL se dela depender o mérito, houve contraditório prévio e efetivo (não na REVELIA) e o juízo era competente em razão da matéria e da pessoa. Art. 504: NÃO fazem coisa julgada I os MOTIVOS, ainda que importantes; II a VERDADE DOS FATOS estabelecida como fundamento." },
  { id: "cpc-181", lei: "CPC", ref: "CPC arts. 505 a 508",
    frente: "Eficácia da coisa julgada: partes, trato continuado, preclusão e eficácia preclusiva (arts. 505 a 508).",
    verso: "Art. 505: nenhum juiz decide de novo questões já decididas, SALVO relação de TRATO CONTINUADO com modificação do estado de fato ou de direito, e demais casos legais. Art. 506: a sentença faz coisa julgada às PARTES entre as quais é dada, NÃO prejudicando TERCEIROS. Art. 507: é vedado rediscutir questões sobre as quais se operou a PRECLUSÃO. Art. 508: transitada em julgado, consideram-se DEDUZIDAS e REPELIDAS todas as alegações e defesas que a parte poderia opor (eficácia preclusiva)." },
  { id: "cpc-182", lei: "CPC", ref: "CPC arts. 509 a 512",
    frente: "Liquidação de sentença: modalidades e regras (arts. 509 a 512).",
    verso: "Sentença que condena a quantia ILÍQUIDA → liquidação, a requerimento do CREDOR ou do DEVEDOR: I por ARBITRAMENTO (determinado na sentença, convencionado ou exigido pela natureza do objeto); II pelo PROCEDIMENTO COMUM (necessidade de alegar e provar FATO NOVO; contestação em 15 DIAS). Parte líquida e parte ilíquida: executa-se a líquida e liquida-se a outra em autos apartados. Só CÁLCULO ARITMÉTICO → cumprimento desde logo. É VEDADO discutir de novo a lide ou modificar a sentença. Pode ser feita na pendência de recurso, em AUTOS APARTADOS no juízo de origem." },
  { id: "cpc-183", lei: "CPC", ref: "CPC art. 513",
    frente: "Cumprimento de sentença que reconhece o dever de pagar quantia: início e forma de intimação do devedor (art. 513).",
    verso: "Provisório ou definitivo, faz-se a REQUERIMENTO do exequente. Devedor intimado: I pelo DIÁRIO DA JUSTIÇA, na pessoa do advogado; II por CARTA com AR (Defensoria ou sem procurador); III por meio ELETRÔNICO (art. 246, §1º, sem procurador); IV por EDITAL, se citado por edital e REVEL na fase de conhecimento. Requerimento após 1 ANO do trânsito em julgado → intimação PESSOAL por carta com AR. NÃO se promove contra FIADOR, COOBRIGADO ou CORRESPONSÁVEL que não participou da fase de conhecimento." },
  { id: "cpc-184", lei: "CPC", ref: "CPC art. 515 · já caiu",
    frente: "Títulos executivos JUDICIAIS (art. 515).",
    verso: "I decisões que reconheçam obrigação de pagar, fazer, não fazer ou entregar; II decisão homologatória de autocomposição JUDICIAL; III homologatória de autocomposição EXTRAJUDICIAL de qualquer natureza; IV formal e certidão de PARTILHA (só quanto a inventariante, herdeiros e sucessores); V crédito de AUXILIAR DA JUSTIÇA aprovado judicialmente; VI SENTENÇA PENAL condenatória transitada em julgado; VII sentença ARBITRAL; VIII sentença ESTRANGEIRA homologada pelo STJ; IX decisão interlocutória estrangeira após exequatur do STJ. Nos incisos VI a IX o devedor é CITADO no juízo cível, para cumprir ou liquidar em 15 DIAS." },
  { id: "cpc-185", lei: "CPC", ref: "CPC art. 516",
    frente: "Juízo competente para o cumprimento da sentença (art. 516).",
    verso: "I os TRIBUNAIS, nas causas de competência originária; II o juízo que decidiu a causa no 1º grau; III o juízo CÍVEL competente, em sentença PENAL condenatória, ARBITRAL, ESTRANGEIRA ou acórdão do Tribunal Marítimo. Nos incisos II e III o exequente pode optar pelo juízo do ATUAL DOMICÍLIO do executado, do LOCAL DOS BENS ou do local onde deva ser executada a obrigação de fazer ou não fazer." },
  { id: "cpc-186", lei: "CPC", ref: "CPC arts. 517 a 519",
    frente: "Protesto da decisão judicial e questões do cumprimento (arts. 517 a 519).",
    verso: "Art. 517: a decisão TRANSITADA em julgado pode ser levada a PROTESTO depois de passado o prazo do art. 523 (15 dias); o exequente apresenta certidão de teor, fornecida em 3 DIAS; o protesto é cancelado em 3 DIAS por determinação do juiz, após satisfação integral. Art. 518: questões sobre a VALIDADE do cumprimento arguem-se nos PRÓPRIOS AUTOS. Art. 519: aplica-se também às decisões que concederem TUTELA PROVISÓRIA." },
  { id: "cpc-187", lei: "CPC", ref: "CPC arts. 520 a 522",
    frente: "Cumprimento PROVISÓRIO de sentença que reconhece obrigação de pagar (arts. 520 a 522).",
    verso: "Cabe contra sentença impugnada por recurso SEM efeito suspensivo. I corre por iniciativa e RESPONSABILIDADE do exequente (repara os danos se reformada); II fica SEM EFEITO se a sentença for modificada ou anulada; III se só em parte, só nesta; IV levantamento de dinheiro, transferência de posse ou alienação e atos de grave dano dependem de CAUÇÃO suficiente e idônea. Multa e honorários de 10% são devidos. Caução DISPENSADA: crédito de natureza ALIMENTAR (qualquer origem); credor em situação de NECESSIDADE; pender agravo do art. 1.042; sentença em consonância com SÚMULA do STF/STJ ou casos repetitivos — mantida a exigência se houver risco manifesto de grave dano." },
  { id: "cpc-188", lei: "CPC", ref: "CPC arts. 523 e 524",
    frente: "Cumprimento definitivo (pagar quantia): prazo, multa e demonstrativo (arts. 523 e 524).",
    verso: "Executado intimado para pagar em 15 DIAS, acrescido de custas. Sem pagamento voluntário: MULTA de 10% e HONORÁRIOS de 10%; pagamento parcial → incidem sobre o RESTANTE; expede-se mandado de PENHORA e AVALIAÇÃO. O requerimento traz demonstrativo discriminado (CPF/CNPJ, índice de correção, juros e taxas, termos inicial e final, capitalização, descontos obrigatórios, bens penhoráveis). Valor aparentemente excessivo: executa-se pelo pretendido, mas a penhora tem por base o que o juiz entender adequado; contabilista do juízo tem 30 DIAS; dados em poder do executado: prazo de até 30 DIAS, senão presumem-se corretos os cálculos do exequente." },
  { id: "cpc-189", lei: "CPC", ref: "CPC art. 525, caput e § 1º · já caiu",
    frente: "Impugnação ao cumprimento de sentença: prazo e matérias (art. 525).",
    verso: "Prazo de 15 DIAS, a contar do fim do prazo do art. 523, independentemente de PENHORA ou nova INTIMAÇÃO, nos próprios autos. Pode alegar: I falta ou nulidade de citação (se correu à REVELIA); II ILEGITIMIDADE de parte; III INEXEQUIBILIDADE do título ou INEXIGIBILIDADE da obrigação; IV PENHORA incorreta ou avaliação errônea; V EXCESSO de execução ou cumulação indevida; VI INCOMPETÊNCIA absoluta ou relativa; VII causa MODIFICATIVA ou EXTINTIVA (pagamento, novação, compensação, transação, prescrição), desde que SUPERVENIENTE à sentença." },
  { id: "cpc-190", lei: "CPC", ref: "CPC art. 525, §§ 4º a 15",
    frente: "Impugnação: excesso de execução, efeito suspensivo e inexigibilidade por decisão do STF (art. 525, §§ 4º a 15).",
    verso: "Excesso de execução: o executado declara de imediato o valor correto com demonstrativo; senão a impugnação é REJEITADA LIMINARMENTE (se for o único fundamento) ou o excesso não é examinado. A impugnação NÃO impede os atos executivos; o juiz pode dar EFEITO SUSPENSIVO a requerimento, se GARANTIDO o juízo (penhora, caução ou depósito), fundamentos relevantes e risco de grave dano; o exequente pode prosseguir mediante CAUÇÃO. Efeito suspensivo a um executado não beneficia os demais se o fundamento lhe for exclusivo. Inexigível também a obrigação fundada em lei declarada INCONSTITUCIONAL pelo STF, em decisão ANTERIOR ao trânsito em julgado; se POSTERIOR, cabe AÇÃO RESCISÓRIA, prazo contado do trânsito da decisão do STF." },
  { id: "cpc-191", lei: "CPC", ref: "CPC art. 526",
    frente: "Pagamento antecipado pelo réu antes da intimação para cumprir (art. 526).",
    verso: "O réu pode, ANTES de ser intimado, depositar o que entende devido com memória de cálculo. O autor é ouvido em 5 DIAS e pode impugnar, sem prejuízo de levantar a parcela incontroversa. Se o depósito for INSUFICIENTE, sobre a DIFERENÇA incidem multa e honorários de 10%. Sem oposição, o juiz declara satisfeita a obrigação e extingue o processo." },
  { id: "cpc-192", lei: "CPC", ref: "CPC arts. 528 e 529 · caiu 2025 Q27",
    frente: "Cumprimento de sentença de ALIMENTOS: prazo, prisão e desconto em folha (arts. 528 e 529).",
    verso: "Executado intimado PESSOALMENTE para, em 3 DIAS, pagar, provar que pagou ou justificar a IMPOSSIBILIDADE (só a ABSOLUTA justifica). Não pagando: PROTESTO e PRISÃO de 1 a 3 MESES, em regime FECHADO, separado dos presos comuns; a prisão não exime do pagamento; paga a prestação, suspende-se a ordem. Prisão civil: débito das 3 ÚLTIMAS prestações anteriores ao ajuizamento e as vincendas. Se o exequente optar pelo rito do art. 523 (expropriação), NÃO há prisão. Pode ser proposto no juízo do DOMICÍLIO do exequente. Art. 529: desconto em FOLHA (servidor, militar, diretor/gerente, empregado); ofício sob pena de DESOBEDIÊNCIA; débito pode ser descontado de forma parcelada, desde que com a parcela devida NÃO ultrapasse 50% dos ganhos líquidos." },
  { id: "cpc-193", lei: "CPC", ref: "CPC arts. 530 a 533",
    frente: "Alimentos: provisórios, definitivos, abandono material e capital (arts. 531 a 533).",
    verso: "Art. 531: aplica-se a alimentos DEFINITIVOS ou PROVISÓRIOS; execução dos provisórios (ou de sentença não transitada) em AUTOS APARTADOS; cumprimento definitivo nos MESMOS autos. Art. 532: conduta procrastinatória → ciência ao MP (crime de ABANDONO MATERIAL). Art. 533: indenização por ato ilícito com alimentos → o executado constitui CAPITAL cuja renda assegure a pensão (inalienável, impenhorável, patrimônio de afetação); pode ser substituído por inclusão em folha de pessoa jurídica de notória capacidade econômica, fiança bancária ou garantia real; a prestação pode tomar por base o SALÁRIO-MÍNIMO." },
  { id: "cpc-194", lei: "CPC", ref: "CPC arts. 534 e 535 · já caiu",
    frente: "Cumprimento de sentença contra a FAZENDA PÚBLICA: multa, prazo e impugnação (arts. 534 e 535).",
    verso: "Exequente apresenta demonstrativo discriminado. A MULTA de 10% do art. 523, §1º NÃO se aplica à Fazenda. Ela é intimada na pessoa do representante judicial (carga, remessa ou meio eletrônico) para impugnar em 30 DIAS, nos próprios autos: falta de citação (revelia), ilegitimidade, inexequibilidade/inexigibilidade, excesso de execução ou cumulação indevida, incompetência, causa modificativa/extintiva SUPERVENIENTE ao trânsito em julgado (NÃO há penhora incorreta). Não impugnada ou rejeitada: PRECATÓRIO por intermédio do presidente do tribunal; ou, em OBRIGAÇÃO DE PEQUENO VALOR, pagamento em 2 MESES da entrega da requisição, por depósito em banco oficial. Impugnação parcial → a parte incontroversa é cumprida desde logo." },
  { id: "cpc-195", lei: "CPC", ref: "CPC arts. 536 e 537 · já caiu: 2013",
    frente: "Obrigação de fazer/não fazer: medidas coercitivas e multa (arts. 536 e 537).",
    verso: "Art. 536: o juiz, de ofício ou a requerimento, determina medidas para a tutela específica ou o resultado equivalente: MULTA, BUSCA E APREENSÃO, REMOÇÃO de pessoas e coisas, DESFAZIMENTO de obras, IMPEDIMENTO de atividade nociva, com força policial se necessário; busca e apreensão cumprida por 2 OFICIAIS DE JUSTIÇA; descumprimento injustificado → LITIGÂNCIA DE MÁ-FÉ e DESOBEDIÊNCIA. Art. 537: a multa INDEPENDE de requerimento, aplica-se na fase de conhecimento (tutela provisória ou sentença) ou na execução, se suficiente, compatível e com PRAZO razoável; o juiz pode modificar o valor ou a periodicidade da VINCENDA ou excluí-la (insuficiente/excessiva; cumprimento parcial ou justa causa); o valor é devido ao EXEQUENTE; cumprimento provisório com depósito em juízo e levantamento após o TRÂNSITO EM JULGADO ou na pendência do agravo do art. 1.042; devida desde o descumprimento." },
  { id: "cpc-196", lei: "CPC", ref: "CPC art. 538",
    frente: "Obrigação de entregar coisa no cumprimento de sentença (art. 538).",
    verso: "Não cumprida no prazo da sentença: mandado de BUSCA E APREENSÃO (coisa MÓVEL) ou de IMISSÃO NA POSSE (coisa IMÓVEL). BENFEITORIAS devem ser alegadas na fase de CONHECIMENTO, na CONTESTAÇÃO, de forma discriminada; o DIREITO DE RETENÇÃO por benfeitorias é exercido na CONTESTAÇÃO. Aplicam-se, no que couber, as regras de fazer e não fazer." },
  { id: "cpc-197", lei: "CPC", ref: "CPC arts. 994 e 995",
    frente: "Recursos cabíveis (art. 994) e efeito da interposição (art. 995).",
    verso: "Art. 994: I APELAÇÃO; II AGRAVO DE INSTRUMENTO; III AGRAVO INTERNO; IV EMBARGOS DE DECLARAÇÃO; V RECURSO ORDINÁRIO; VI RECURSO ESPECIAL; VII RECURSO EXTRAORDINÁRIO; VIII AGRAVO em REsp ou RE; IX EMBARGOS DE DIVERGÊNCIA. (NÃO há mais agravo retido nem embargos infringentes.) Art. 995: os recursos NÃO impedem a eficácia da decisão, salvo disposição legal ou decisão judicial; o relator pode suspendê-la se houver risco de dano grave, de difícil ou impossível reparação, e probabilidade de provimento." },
  { id: "cpc-198", lei: "CPC", ref: "CPC arts. 996 e 997 · já caiu: 2012, 2023",
    frente: "Legitimidade para recorrer e recurso ADESIVO (arts. 996 e 997).",
    verso: "Art. 996: pode recorrer a PARTE VENCIDA, o TERCEIRO PREJUDICADO e o MP (como parte ou fiscal da ordem jurídica). Art. 997: cada parte recorre independentemente; sendo vencidos AUTOR e RÉU, ao recurso de um pode ADERIR o outro. O adesivo é SUBORDINADO ao principal: dirigido ao órgão do recurso principal, no prazo das CONTRARRAZÕES; cabe em APELAÇÃO, RECURSO EXTRAORDINÁRIO e RECURSO ESPECIAL; NÃO é conhecido se houver DESISTÊNCIA do principal ou se este for inadmissível." },
  { id: "cpc-199", lei: "CPC", ref: "CPC arts. 998 a 1002 · já caiu: 2011, 2012, 2014, 2018, 2023",
    frente: "Desistência, renúncia e aceitação da decisão (arts. 998 a 1002).",
    verso: "Art. 998: o recorrente pode, A QUALQUER TEMPO, SEM anuência do recorrido ou dos litisconsortes, DESISTIR do recurso; isso não impede a análise de questão de repercussão geral já reconhecida ou de recursos repetitivos. Art. 999: a RENÚNCIA ao direito de recorrer INDEPENDE da aceitação da outra parte. Art. 1.000: quem aceitar expressa ou tacitamente a decisão NÃO pode recorrer (aceitação tácita = ato incompatível praticado SEM reserva). Art. 1.001: dos DESPACHOS NÃO cabe recurso. Art. 1.002: a decisão pode ser impugnada no todo ou em parte." },
  { id: "cpc-200", lei: "CPC", ref: "CPC art. 1.003 · já caiu",
    frente: "Prazo para recorrer: contagem e regras (art. 1.003).",
    verso: "O prazo conta-se da INTIMAÇÃO dos advogados, Advocacia Pública, Defensoria ou MP; intimados em audiência quando a decisão for nela proferida. Prazo geral: 15 DIAS para interpor e para responder — EXCETO os EMBARGOS DE DECLARAÇÃO (5 dias). Recurso remetido pelo CORREIO: vale a data da POSTAGEM. O recorrente comprova FERIADO LOCAL no ato de interposição. Réu que recorre de decisão anterior à citação: aplica-se o art. 231, I a VI." },
  { id: "cpc-201", lei: "CPC", ref: "CPC arts. 1.004 a 1.006 · caiu 2025 Q28",
    frente: "Restituição de prazo, litisconsortes e baixa dos autos (arts. 1.004 a 1.006).",
    verso: "Art. 1.004: se, no prazo, sobrevier FALECIMENTO da parte ou do advogado ou FORÇA MAIOR que suspenda o processo, o prazo é RESTITUÍDO (começa a correr de novo após a intimação). Art. 1.005: o recurso de um litisconsorte a todos aproveita, SALVO interesses distintos ou opostos; na solidariedade passiva, aproveita se as defesas forem comuns. Art. 1.006: certificado o trânsito em julgado com a data, o escrivão providencia a baixa dos autos em 5 DIAS, independentemente de despacho." },
  { id: "cpc-202", lei: "CPC", ref: "CPC art. 1.007 · já caiu: 2023",
    frente: "Preparo e deserção (art. 1.007).",
    verso: "O preparo (inclusive porte de remessa e de retorno) é comprovado NO ATO de interposição, sob pena de DESERÇÃO. DISPENSADOS: MP, União, Estados, DF, Municípios, autarquias e quem tem isenção legal. Insuficiência do valor: deserção se não suprir em 5 DIAS após intimação. Autos ELETRÔNICOS: dispensa-se o porte de remessa e retorno. Sem comprovar o preparo: intimado a recolher em DOBRO, sob pena de deserção; NÃO se complementa insuficiência parcial do dobro. JUSTO IMPEDIMENTO: o relator relevará a deserção (decisão irrecorrível) e dá 5 DIAS. ERRO no preenchimento da guia NÃO gera deserção (5 dias para sanar a dúvida)." },
  { id: "cpc-203", lei: "CPC", ref: "CPC art. 1.008",
    frente: "Efeito substitutivo do julgamento do recurso (art. 1.008).",
    verso: "O julgamento proferido pelo TRIBUNAL SUBSTITUI a decisão impugnada NO QUE TIVER SIDO OBJETO DE RECURSO." },
  { id: "cpc-204", lei: "CPC", ref: "CPC arts. 1.009 e 1.010",
    frente: "Apelação: cabimento, preliminar e requisitos (arts. 1.009 e 1.010).",
    verso: "Art. 1.009: da SENTENÇA cabe apelação. Decisões interlocutórias NÃO agraváveis NÃO preclui: suscitam-se em PRELIMINAR de apelação ou nas CONTRARRAZÕES (recorrente ouvido em 15 DIAS). Art. 1.010: petição dirigida ao juízo de 1º GRAU com nomes e qualificação das partes, exposição do fato e do direito, razões do pedido de reforma ou nulidade e pedido de nova decisão. Apelado intimado a contra-arrazoar em 15 DIAS; apelação adesiva → apelante contra-arrazoa. Os autos SOBEM ao tribunal independentemente de JUÍZO DE ADMISSIBILIDADE no 1º grau." },
  { id: "cpc-205", lei: "CPC", ref: "CPC art. 1.011",
    frente: "Julgamento da apelação pelo relator (art. 1.011).",
    verso: "Distribuída imediatamente, o relator decide monocraticamente APENAS nas hipóteses do art. 932, III a V (inadmissível/prejudicada/não impugnou; negar ou dar provimento conforme súmula, repetitivo, IRDR); nos demais casos elabora voto para o ÓRGÃO COLEGIADO." },
  { id: "cpc-206", lei: "CPC", ref: "CPC art. 1.012 · já caiu: 2007",
    frente: "Efeito da apelação e sentenças com eficácia imediata (art. 1.012).",
    verso: "Regra: a apelação tem efeito SUSPENSIVO. EXCEÇÕES — a sentença produz efeitos IMEDIATAMENTE quando: I homologa DIVISÃO ou DEMARCAÇÃO de terras; II condena a pagar ALIMENTOS; III EXTINGUE sem mérito ou julga IMPROCEDENTES os embargos do executado; IV julga procedente pedido de instituição de ARBITRAGEM; V confirma, concede ou revoga TUTELA PROVISÓRIA; VI decreta INTERDIÇÃO. Efeito suspensivo nesses casos: pedido ao TRIBUNAL (entre a interposição e a distribuição — relator fica prevento) ou ao RELATOR (se já distribuída)." },
  { id: "cpc-207", lei: "CPC", ref: "CPC arts. 1.013 e 1.014 · já caiu: 2007",
    frente: "Efeito devolutivo e teoria da causa madura (arts. 1.013 e 1.014).",
    verso: "Art. 1.013: a apelação devolve a matéria IMPUGNADA; o tribunal aprecia todas as questões suscitadas e discutidas, ainda que não solucionadas, relativas ao capítulo impugnado; mais de um fundamento e juiz acolheu um → devolve os DEMAIS. Julga desde logo o mérito, se em condições, quando: I reformar sentença do art. 485; II sentença NÃO congruente (extra/ultra/citra petita nos limites do pedido ou causa de pedir); III omissão no exame de UM dos pedidos; IV nulidade por falta de FUNDAMENTAÇÃO; também ao reformar sentença que reconheceu decadência ou prescrição. Art. 1.014: questões de FATO não propostas no 1º grau só na apelação se provado FORÇA MAIOR." },
  { id: "cpc-208", lei: "CPC", ref: "CPC art. 1.015 · já caiu: 2011",
    frente: "Agravo de instrumento: decisões interlocutórias recorríveis (art. 1.015).",
    verso: "Versarem sobre: I TUTELAS PROVISÓRIAS; II MÉRITO do processo; III rejeição de CONVENÇÃO DE ARBITRAGEM; IV DESCONSIDERAÇÃO da personalidade jurídica; V rejeição do pedido de GRATUIDADE ou acolhimento de sua revogação; VI EXIBIÇÃO ou posse de documento ou coisa; VII EXCLUSÃO de litisconsorte; VIII rejeição de LIMITAÇÃO do litisconsórcio; IX admissão ou inadmissão de INTERVENÇÃO DE TERCEIROS; X efeito suspensivo aos EMBARGOS À EXECUÇÃO; XI redistribuição do ÔNUS DA PROVA (art. 373, §1º); XIII outros casos em lei. Também cabe, SEM rol taxativo, na LIQUIDAÇÃO, CUMPRIMENTO DE SENTENÇA, EXECUÇÃO e INVENTÁRIO (parágrafo único)." },
  { id: "cpc-209", lei: "CPC", ref: "CPC arts. 1.016 a 1.018",
    frente: "Agravo de instrumento: interposição, instrução e comunicação ao juiz (arts. 1.016 a 1.018).",
    verso: "Art. 1.016: dirigido DIRETAMENTE ao TRIBUNAL, com nomes das partes, exposição do fato e direito, razões e pedido, nome e endereço dos advogados. Art. 1.017: peças OBRIGATÓRIAS: petição inicial, contestação, petição que ensejou a decisão, a decisão agravada, certidão de intimação e procurações; ou declaração de inexistência pelo advogado; FACULTATIVAS: outras úteis. Autos ELETRÔNICOS: dispensam-se as peças obrigatórias. Falta de peça ou vício sanável: o relator concede prazo (art. 932, par. único). Art. 1.018: o agravante PODE requerer a juntada de cópia ao juízo de 1º grau; se o juiz REFORMAR inteiramente, o agravo fica PREJUDICADO; autos NÃO eletrônicos: 3 DIAS; descumprimento arguido e provado pelo agravado → INADMISSIBILIDADE." },
  { id: "cpc-210", lei: "CPC", ref: "CPC arts. 1.019 e 1.020",
    frente: "Agravo de instrumento no tribunal: atos do relator (arts. 1.019 e 1.020).",
    verso: "Em 5 DIAS da distribuição o relator: I pode atribuir EFEITO SUSPENSIVO ou deferir ANTECIPAÇÃO DE TUTELA recursal, comunicando o juiz; II manda INTIMAR o agravado para responder em 15 DIAS; III intima o MP, quando for o caso, para manifestar-se em 15 DIAS. Art. 1.020: o relator pede dia para julgamento em prazo NÃO superior a 1 MÊS da intimação do agravado." },
  { id: "cpc-211", lei: "CPC", ref: "CPC art. 1.021 · caiu 2024 Q42 · já caiu: 2017",
    frente: "Agravo interno (art. 1.021).",
    verso: "Cabe contra decisão do RELATOR, para o ÓRGÃO COLEGIADO. O recorrente impugna ESPECIFICAMENTE os fundamentos da decisão. Dirigido ao relator, que intima o agravado para responder em 15 DIAS; sem retratação, leva a julgamento. É VEDADO ao relator limitar-se a reproduzir os fundamentos da decisão agravada. Se declarado manifestamente INADMISSÍVEL ou IMPROCEDENTE por votação UNÂNIME: MULTA de 1% a 5% do valor atualizado da causa; outro recurso só com DEPÓSITO prévio da multa (exceto Fazenda Pública e beneficiário de gratuidade, que pagam ao final)." },
  { id: "cpc-212", lei: "CPC", ref: "CPC art. 1.022 · já caiu: 2021",
    frente: "Embargos de declaração: cabimento e decisão omissa (art. 1.022).",
    verso: "Contra QUALQUER decisão judicial para: I esclarecer OBSCURIDADE ou eliminar CONTRADIÇÃO; II suprir OMISSÃO de ponto ou questão sobre o qual devia se pronunciar o juiz; III corrigir ERRO MATERIAL. É omissa a decisão que: deixa de se manifestar sobre tese firmada em casos REPETITIVOS ou incidente de assunção de competência; ou incorre em qualquer das condutas do art. 489, §1º (não fundamentada)." },
  { id: "cpc-213", lei: "CPC", ref: "CPC arts. 1.023 e 1.024 · já caiu: 2013, 2021",
    frente: "Embargos de declaração: prazo, preparo e julgamento (arts. 1.023 e 1.024).",
    verso: "Opostos em 5 DIAS, por petição ao juiz, indicando erro, obscuridade, contradição ou omissão; NÃO se sujeitam a PREPARO; aplica-se o art. 229 (prazo em dobro p/ litisconsortes com advogados diferentes). O juiz intima o embargado em 5 DIAS se o acolhimento puder MODIFICAR a decisão. Juiz julga em 5 DIAS; nos tribunais, o relator apresenta em mesa na sessão SUBSEQUENTE (senão, pauta automática). Contra decisão unipessoal, o prolator decide MONOCRATICAMENTE. Podem ser conhecidos como AGRAVO INTERNO, com intimação prévia do recorrente (5 dias) para complementar razões. Acolhimento que modifica a decisão: quem já recorreu pode complementar razões em 15 DIAS; rejeitados, o recurso anterior da outra parte é julgado SEM ratificação." },
  { id: "cpc-214", lei: "CPC", ref: "CPC arts. 1.025 e 1.026 · já caiu: 2021",
    frente: "Embargos de declaração: prequestionamento, efeitos e multa (arts. 1.025 e 1.026).",
    verso: "Art. 1.025: consideram-se INCLUÍDOS no acórdão os elementos suscitados para fins de PREQUESTIONAMENTO, ainda que os embargos sejam inadmitidos ou rejeitados, se o tribunal superior considerar existentes erro, omissão, contradição ou obscuridade. Art. 1.026: NÃO têm efeito SUSPENSIVO e INTERROMPEM o prazo para outros recursos (não suspendem); eficácia pode ser suspensa pelo juiz/relator (probabilidade de provimento ou risco de dano). Manifestamente PROTELATÓRIOS: multa de até 2% do valor da causa; REITERAÇÃO: até 10%, e outro recurso condicionado ao depósito (exceto Fazenda e gratuidade); NÃO se admitem novos embargos se os 2 anteriores foram protelatórios." }
]);
